INSERT INTO fact_claims (lesson_id, position, text_en, text_de, text_pl, source) VALUES
  ('money', 0, 'Barter needs a ''double coincidence of wants'': each side must have something the other side wants.', 'Tauschhandel braucht das ''doppelte Zusammentreffen von Wünschen'': Jede Seite muss haben, was die andere will.', 'Handel wymienny wymaga tzw. ''podwójnej zbieżności potrzeb'': każda ze stron musi chcieć tego, co oferuje druga.', 'https://www.stlouisfed.org/publications/page-one-economics/2013/03/01/money-and-inflation-a-functional-relationship'),
  ('money', 1, 'With money as a medium of exchange, the two sides no longer need to want each other''s goods.', 'Mit Geld als Tauschmittel müssen die beiden Seiten nicht mehr gegenseitig die Waren des anderen wollen.', 'Dzięki pieniądzom jako środkowi wymiany dwie strony nie muszą już nawzajem potrzebować swoich towarów.', 'https://www.ecb.europa.eu/home/pdf/students/booklet_en.pdf'),
  ('money', 2, 'Money has three functions: medium of exchange, unit of account (prices), store of value.', 'Geld hat drei Funktionen: Tauschmittel, Recheneinheit (Preise), Wertaufbewahrungsmittel.', 'Pieniądz pełni trzy funkcje: środek wymiany, jednostka rozliczeniowa (ceny) oraz środek przechowywania wartości.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/what_is_money.en.html'),
  ('money', 3, 'India uses the Indian Rupee (₹), Germany uses the Euro (€), and Poland uses the Polish Złoty (zł).', 'Deutschland nutzt den Euro (€), Polen den Złoty (zł) und Indien die Rupie (₹).', 'Polska używa złotego (zł), Niemcy euro (€), a Indie rupii indyjskiej (₹).', 'https://www.ecb.europa.eu/euro/intro/html/map.en.html'),
  ('money', 4, 'Circulating coins and banknotes represent standard currency divisions (e.g. 100 paise per rupee, 100 cents per euro, 100 groszy per złoty).', 'Umlaufende Münzen und Banknoten stellen Standard-Währungsunterteilungen dar (z. B. 100 Cent pro Euro, 100 Groszy pro Złoty, 100 Paise pro Rupie).', 'Obiegowe monety i banknoty reprezentują standardowe podziały waluty (np. 100 groszy na złoty, 100 centów na euro, 100 paise na rupię).', 'https://www.ecb.europa.eu/euro/coins/html/index.en.html'),
  ('work', 0, 'In the labor market, the ''good'' that is bought and sold is labor, and its price is the wage. The labor market works like other markets, with buyers and sellers who set a price.', 'Auf dem Arbeitsmarkt ist das gehandelte Gut die Arbeit, und ihr Preis ist der Lohn. Der Arbeitsmarkt funktioniert wie andere Märkte mit Angebot und Nachfrage.', 'Na rynku pracy ''towarem'', który podlega kupnu i sprzedaży, jest praca, a jej ceną jest wynagrodzenie. Rynek pracy działa jak inne rynki z kupującymi i sprzedającymi.', 'https://www.federalreserveeducation.org/teaching-resources/economics/labor-income/the-labor-market-podcast'),
  ('work', 1, 'Workers can raise their productivity and wages by gaining skill, education and training. For higher wages, economists advise professions with high demand but relatively small supply of qualified providers.', 'Arbeitskräfte können ihre Produktivität und Löhne durch Fähigkeiten, Bildung und Ausbildung steigern. Höhere Löhne erzielen Berufe mit hoher Nachfrage und knappem Angebot an Fachkräften.', 'Pracownicy mogą podnosić swoją produktywność i zarobki poprzez zdobywanie umiejętności i wykształcenia. Wyższe płace oferują zawody o wysokim popycie i ograniczonej liczbie wykwalifikowanych specjalistów.', 'https://www.federalreserveeducation.org/teaching-resources/economics/labor-income/the-labor-market-podcast'),
  ('work', 2, 'Pay within a job type varies with market conditions such as the number of jobs available and the number of qualified candidates, and consumer demand for what the worker produces affects earnings.', 'Die Bezahlung variiert mit den Marktbedingungen wie der Anzahl offener Stellen, der Zahl qualifizierter Bewerber und der Nachfrage nach den erzeugten Gütern.', 'Płace w danym zawodzie zależą od warunków rynkowych, takich jak liczba dostępnych miejsc pracy, liczba kandydatów oraz popyt na wytwarzane dobra.', 'https://www.dallasfed.org/~/media/documents/educate/navigate/navigateunit1.pdf'),
  ('work', 3, 'Statutory minimum wages protect workers by ensuring a legally mandated wage floor across sectors, while skilled roles command higher market earnings based on training.', 'Gesetzliche Mindestlöhne schützen Arbeitnehmer durch eine verbindliche Lohnuntergrenze, während qualifizierte Berufe je nach Ausbildung höhere Marktlöhne erzielen.', 'Ustawowa płaca minimalna chroni pracowników, zapewniając prawnie gwarantowany próg zarobków, podczas gdy zawody specjalistyczne osiągają wyższe wynagrodzenia rynkowe.', 'https://www.bmas.de/DE/Arbeit/Arbeitsrecht/Mindestlohn/Informationen-zum-Mindestlohn/informationen-zum-mindestlohn-deutsch.html'),
  ('work', 4, 'Gross (brutto) pay is earnings before taxes and social security contributions are deducted. Net (netto) pay is the take-home amount after mandatory statutory deductions.', 'Der Bruttolohn ist das Gehalt vor Abzug von Steuern und Sozialabgaben. Der Nettolohn ist der Auszahlungsbetrag, der nach allen Abzügen übrig bleibt.', 'Wynagrodzenie brutto to kwota przed potrąceniem podatków i składek na ubezpieczenia społeczne. Wynagrodzenie netto (na rękę) to kwota wypłacana pracownikowi po potrąceniach.', 'https://www.bpb.de/kurz-knapp/lexika/das-junge-politik-lexikon/319967/bruttolohn-nettolohn/'),
  ('savings', 0, 'Savings is money you set aside today to use in the future. People save for things like a bill that is due, school supplies, or personal goals like a car or an appliance.', 'Ersparnisse sind Geld, das man heute zurücklegt, um es in der Zukunft zu nutzen: für Rechnungen, Schulbedarf oder persönliche Ziele.', 'Oszczędności to pieniądze odkładane dzisiaj z myślą o przyszłości. Ludzie oszczędzają na rachunki, wyprawkę szkolną lub cele osobiste.', 'https://files.consumerfinance.gov/f/documents/cfpb_your-money-your-goals_savings_booklet_cobrand.pdf'),
  ('savings', 1, 'Unexpected expenses can get in the way of reaching a savings goal, so building a ''rainy day fund'' helps people stay on track with emergencies.', 'Unerwartete Ausgaben können Sparziele gefährden. Ein Notgroschen hilft, unvorhergesehene Reparaturen abzufedern.', 'Niespodziewane wydatki mogą pokrzyżować cele oszczędnościowe, dlatego fundusz awaryjny pomaga bezpiecznie radzić sobie z nagłymi zdarzeniami.', 'https://www.consumerfinance.gov/an-essential-guide-to-building-an-emergency-fund/'),
  ('savings', 2, 'Even a small amount put aside regularly provides financial resilience and prevents unexpected costs from turning into debt.', 'Schon kleine, regelmäßig gesparte Beträge schaffen finanzielle Sicherheit und verhindern, dass Notfälle zu Schulden führen.', 'Nawet małe kwoty odkładane regularnie dają odporność finansową i chronią przed popadaniem w długi w nagłych sytuacjach.', 'https://www.consumerfinance.gov/an-essential-guide-to-building-an-emergency-fund/'),
  ('savings', 3, 'Minor banking accounts and pocket money guidelines give children structured ways to practice budgeting small everyday decisions.', 'Kinderkonten und Taschengelderziehung geben Heranwachsenden einen verlässlichen Rahmen, um den Umgang mit Geld im Alltag zu üben.', 'Konta dla dzieci i kieszonkowe dają najmłodszym bezpieczne warunki do nauki planowania budżetu i podejmowania codziennych decyzji finansowych.', 'https://www.verbraucherzentrale.de/podcast-umgang-mit-geld-infos-rund-ums-taschengeld-125596'),
  ('savings', 4, 'Emergency cushions of a few months of living costs are standard household recommendations across modern financial education guidance.', 'Finanzexperten empfehlen Haushalten üblicherweise eine finanzielle Reserve von zwei bis drei Monatsgehältern für Unvorhergesehenes.', 'Eksperci finansowi zalecają gospodarstwom domowym utrzymywanie poduszki finansowej równej kosztom życia z kilku miesięcy.', 'https://www.verbraucherzentrale.de/laura-zieht-aus/sparen'),
  ('business', 0, 'In economics, profit is the residual surplus remaining after total business operating expenses, material costs, and wages are subtracted from revenue.', 'Der unternehmerische Gewinn ist der Überschuss der Erträge über die Aufwendungen einer Abrechnungsperiode.', 'Zysk przedsiębiorstwa stanowi dodatnią różnicę między uzyskanymi przychodami a poniesionymi kosztami działalności.', 'https://wirtschaftslexikon.gabler.de/definition/gewinn-33630'),
  ('business', 1, 'Labor laws require employers to pay agreed contractual employee wages regardless of whether the business generated a profit or suffered a trading loss.', 'Das Arbeitsrecht verpflichtet Arbeitgeber zur Lohnzahlung unabhängig davon, ob das Unternehmen in der Periode Gewinn oder Verlust erzielt.', 'Kodeks pracy nakłada na pracodawcę obowiązek terminowej wypłaty wynagrodzenia pracownikom niezależnie od wyniku finansowego firmy.', 'https://www.gesetze-im-internet.de/bgb/__611a.html'),
  ('business', 2, 'Commercial codes define an entrepreneur as an individual or legal entity that independently engages in economic activity while bearing financial risk.', 'Als Unternehmer gilt nach Handels- und Zivilrecht jede natürliche oder juristische Person, die selbstständig am Markt wirtschaftlich handelt und das Verlustrisiko trägt.', 'Ustawa Prawo przedsiębiorców definiuje przedsiębiorcę jako podmiot wykonujący działalność gospodarczą we własnym imieniu w sposób zorganizowany i ciągły.', 'https://www.gesetze-im-internet.de/bgb/__14.html'),
  ('business', 3, 'Economic data shows that small enterprises must balance fixed operational overhead against variable demand driven by seasonality and consumer trends.', 'Statistische Ämter erfassen Kostenstrukturen und Umsätze von Kleinbetrieben, um den Einfluss von Fixkosten und saisonalen Schwankungen abzubilden.', 'Główny Urząd Statystyczny (GUS) bada strukturę kosztów i przychodów małych przedsiębiorstw, wskazując na wpływ kosztów stałych na rentowność.', 'https://www.destatis.de/DE/Themen/Wirtschaft/Unternehmen/_inhalt.html'),
  ('business', 4, 'Central banking and development agencies emphasize that healthy business profit provides the vital retained capital needed to reinvest in productivity.', 'Wirtschaftsforschungsinstitute betonen, dass nachhaltige Gewinne von Unternehmen unabdingbar sind, um Investitionen zu finanzieren und Rücklagen zu bilden.', 'Instytucje finansowe podkreślają, że wypracowany zysk stanowi podstawowe źródło kapitału własnego na inwestycje i zabezpieczenie przed kryzysem.', 'https://www.ecb.europa.eu/ecb/educational/html/index.en.html'),
  ('equity', 0, 'Corporate law defines equity as the residual ownership interest in the assets of an enterprise after all liabilities and debt obligations are settled.', 'Das Eigenkapital repräsentiert den rechnerischen Residualanspruch der Unternehmenseigner an den Vermögenswerten nach Abzug aller Verbindlichkeiten.', 'Kapitał własny stanowi wartość aktywów przedsiębiorstwa przysługującą jego właścicielom po odliczeniu wszystkich zobowiązań.', 'https://wirtschaftslexikon.gabler.de/definition/eigenkapital-35324'),
  ('equity', 1, 'Partnership and company law permits investors to acquire fractional ownership shares in a business and receive proportionate profit distributions.', 'Das Gesellschaftsrecht regelt, dass Mitgesellschafter entsprechend ihrer Beteiligungsquote am Gewinn und Verlust der Gesellschaft partizipieren.', 'Kodeks spółek handlowych określa zasady obejmowania udziałów w spółkach oraz prawo wspólników do równego lub proporcjonalnego udziału w zysku.', 'https://www.gesetze-im-internet.de/gmbhg/__29.html'),
  ('equity', 2, 'Financial accounting classifies productive tools, vehicles, and equipment as productive capital assets that generate recurring economic benefits over multi-year useful lives.', 'Im betrieblichen Rechnungswesen zählen Sachanlagen wie Maschinen und Ausrüstung zum Anlagevermögen, das dem Geschäftsbetrieb dauerhaft dient.', 'Ustawa o rachunkowości zalicza maszyny, urządzenia i środki transportu do rzeczowych aktywów trwałych służących do generowania przychodów.', 'https://www.gesetze-im-internet.de/hgb/__247.html'),
  ('equity', 3, 'Economic data tracks gross fixed capital formation to measure how much enterprises invest in productive machinery and infrastructure to expand output.', 'Statistische Ämter erfassen Bruttoanlageinvestitionen von Unternehmen, um die Ausstattung der Wirtschaft mit produktivem Sachkapital abzubilden.', 'Główny Urząd Statystyczny (GUS) publikuje dane o nakładach brutto na środki trwałe, ilustrując inwestycje firm w nowoczesny park maszynowy.', 'https://www.destatis.de/DE/Themen/Wirtschaft/Volkswirtschaftliche-Gesamtrechnungen-Inlandsprodukt/_inhalt.html'),
  ('equity', 4, 'Central banks highlight that equity capital formation enables enterprises to scale productivity and share business yields with savers and co-investors.', 'Zentralbanken betonen die volkswirtschaftliche Rolle von Eigenkapital als risikotragende Basis für Innovation, Wachstum und Wertschöpfung.', 'Narodowy Bank Polski (NBP) w raportach o stabilności systemu finansowego podkreśla kluczowe znaczenie kapitału własnego firm dla odporności na kryzysy.', 'https://nbp.pl/system-finansowy/rozwoj-systemu-finansowego/'),
  ('loans', 0, 'In contract law, a loan agreement obliges the lender to hand over the agreed sum and the borrower to repay the loan when it falls due, along with any agreed interest.', 'Im deutschen Recht verpflichtet ein Darlehensvertrag den Darlehensgeber zur Auszahlung und den Darlehensnehmer zur Rückzahlung und Zinszahlung bei Fälligkeit (BGB § 488).', 'W prawie umowa pożyczki zobowiązuje pożyczkodawcę do przekazania ustalonej kwoty, a pożyczkobiorcę do zwrotu kwoty i ewentualnych odsetek w terminie (np. Kodeks cywilny art. 720).', 'https://www.gesetze-im-internet.de/bgb/__488.html'),
  ('loans', 1, 'Borrowing now to build something that pays later, with the lender getting back more than was lent, illustrates the trade-off between consuming now and investing for greater future income.', 'Heute leihen, um etwas Produktives aufzubauen, verdeutlicht den ökonomischen Tausch zwischen sofortigem Konsum und Investition in künftigen Ertrag.', 'Pożyczanie dzisiaj na inwestycję, która przyniesie zysk w przyszłości, obrazuje równowagę między natychmiastową konsumpcją a inwestowaniem w rozwój.', 'https://www.europarl.europa.eu/workingpapers/econ/116/116_en.htm'),
  ('loans', 2, 'Interest acts as compensation to induce savers to part with money rather than spend it immediately.', 'Zinsen sind der Preis, der Sparer dazu bewegt, ihr Geld vorübergehend herzugeben, statt es selbst sofort auszugeben.', 'Odsetki stanowią wynagrodzenie zachęcające oszczędzających do powierzenia swoich środków zamiast ich natychmiastowego wydania.', 'https://www.europarl.europa.eu/workingpapers/econ/116/116_en.htm'),
  ('loans', 3, 'Lenders consider credit risk: the greater the risk that a borrower cannot repay, the higher the rate they charge to compensate for possible defaults.', 'Kreditgeber berücksichtigen Ausfallrisiken: Je höher das Risiko eines Zahlungsausfalls, desto höher fallen die Zinsen aus.', 'Kredytodawcy oceniają ryzyko kredytowe: im większe ryzyko braku spłaty, tym wyższe oprocentowanie rekompensujące ewentualne straty.', 'https://www.bankofengland.co.uk/explainers/what-are-interest-rates'),
  ('loans', 4, 'Consumer protection rules require transparent credit contracts displaying interest rates, number of instalments, and total repayments before signing.', 'Verbraucherschutzgesetze verlangen transparente Verträge, die effektiven Jahreszins, Raten und den Gesamtbetrag vor Vertragsschluss ausweisen.', 'Przepisy o kredycie konsumenckim wymagają przejrzystej umowy zawierającej RRSO, harmonogram rat oraz całkowitą kwotę do spłaty.', 'https://www.verbraucherzentrale.de/wissen/geld-versicherungen/kredit-schulden-insolvenz/kredite-und-darlehen-auch-beim-geldleihen-laesst-sich-sparen-10409'),
  ('banks', 0, 'A bank''s main role is to take in deposits from people who have money, pool them, and lend them to people who need funds. Banks act as financial intermediaries.', 'Die Hauptaufgabe einer Bank besteht darin, Einlagen anzunehmen, zu bündeln und an Kreditnehmer weiterzuleiten (Finanzintermediation).', 'Główną rolą banku jest przyjmowanie depozytów, łączenie ich i udzielanie kredytów podmiotom potrzebującym finansowania (pośrednictwo finansowe).', 'https://www.imf.org/en/publications/fandd/issues/series/back-to-basics/banks'),
  ('banks', 1, 'Banks operate with fractional reserves: they keep a fraction of deposits available because depositors rarely withdraw all funds simultaneously.', 'Banken arbeiten mit Teilreservern: Sie halten nur einen Teil als Barreserve, da Sparer ihr Geld selten gleichzeitig bar abheben.', 'Banki działają w systemie rezerwy cząstkowej: utrzymują w gotowości tylko część środków, ponieważ klienci rzadko wypłacają wszystko naraz.', 'https://publikationen.bundesbank.de/publikationen-de/schule-bildung/geld-und-geldpolitik-921580?article=3-banken-und-buchgeld-922604'),
  ('banks', 2, 'A sudden wave of withdrawals where savers rush to pull out funds before liquid assets run dry is called a bank run.', 'Wenn viele Sparer aus Sorge gleichzeitig ihr Geld abheben wollen, spricht man von einem Bankansturm (Bank Run).', 'Masowe i nagłe wycofywanie oszczędności przez zaniepokojonych klientów to panika bankowa (bank run).', 'https://www.stlouisfed.org/publications/regional-economist/2023/may/interest-rate-risk-bank-runs'),
  ('banks', 3, 'Statutory deposit insurance funds protect savers'' deposits up to official limits (e.g. 100,000 EUR in the EU, 5 lakh INR in India), preventing panic.', 'Gesetzliche Einlagensicherungen schützen Bankguthaben bis zu gesetzlichen Höchstgrenzen (z. B. 100.000 EUR in der EU) und beruhigen Sparer.', 'Ustawowe systemy gwarantowania depozytów (np. BFG w Polsce, 100 000 EUR) chronią oszczędności obywateli i zapobiegają panice.', 'https://www.bundesbank.de/en/tasks/financial-supervision/individual-aspects/deposit-protection-622748'),
  ('banks', 4, 'Most money today is electronic ''book money'' created in the banking system; digital payments and card transfers update accounting ledgers without physical cash.', 'Das meiste Geld ist heute digitales Buchgeld; Kartenzahlungen und Überweisungen verändern Computereinträge ohne Münzen.', 'Większość dzisiejszego pieniądza to pieniądz bezgotówkowy (elektroniczny); płatności kartą i przelewy aktualizują salda na kontach bez fizycznej gotówki.', 'https://www.bankofengland.co.uk/explainers/how-is-money-created'),
  ('interest', 0, 'Interest is the price of borrowing money. The interest rate is shown in percent (''out of a hundred'') and says what share of the saved or borrowed amount is charged as interest.', 'Zinsen sind der Preis für geliehenes Geld. Der Zinssatz wird in Prozent angegeben und bestimmt den Anteil am Betrag.', 'Odsetki to koszt pożyczenia pieniędzy. Stopa procentowa wyrażana jest w procentach i określa, jaka część pożyczonej lub zaoszczędzonej kwoty stanowi odsetki.', 'https://www.bundesbank.de/de/service/schule-und-bildung/erklaerfilme/was-sind-zinsen--860012'),
  ('interest', 1, 'A bank can pay its savers interest on their deposits, and a borrower must pay interest to the bank. The higher the risk that a borrower cannot repay, the higher the loan rate.', 'Eine Bank zahlt Sparern Zinsen auf Einlagen; Kreditnehmer zahlen Zinsen an die Bank. Je höher das Ausfallrisiko, desto höher der Zins.', 'Bank płaci oszczędzającym odsetki od depozytów, a pożyczkobiorca płaci odsetki bankowi. Im większe ryzyko niespłacenia pożyczki, tym wyższe oprocentowanie.', 'https://www.bundesbank.de/de/service/schule-und-bildung/erklaerfilme/was-sind-zinsen--860012'),
  ('interest', 2, 'Lending and taking deposits are among the most important functions of banks. Borrowers pay interest to the bank, the bank pays interest on customer deposits, and the difference (Zinsmarge) is one of banks'' most important sources of income.', 'Kredit- und Einlagengeschäft sind Kernfunktionen von Banken. Die Differenz zwischen Aktiv- und Passivzinsen (Zinsmarge) bildet eine Haupteinnahmequelle.', 'Udzielanie kredytów i przyjmowanie depozytów to kluczowe funkcje banków. Różnica między oprocentowaniem kredytów a depozytów (marża odsetkowa) to główne źródło dochodu banków.', 'https://publikationen.bundesbank.de/content/922604.md'),
  ('interest', 3, 'Banks price loans to cover capital costs, expected losses from defaults, funding costs and running costs.', 'Banken kalkulieren Kreditzinsen so, dass sie Eigenkapitalkosten, erwartete Kreditausfälle und Betriebskosten decken.', 'Banki ustalają oprocentowanie kredytów tak, aby pokryć koszty operacyjne, ryzyko niewypłacalności i koszty finansowania.', 'https://publikationen.bundesbank.de/caas/v1/media/794132/data/9d633327cfea2255dfa059fe89f2cef1'),
  ('interest', 4, 'Compound interest is interest earned on interest: 100 at 5% a year becomes 105 after one year and 110.25 after two, because the second year''s interest is paid on 105.', 'Zinseszins bedeutet Zinsen auf Zinsen: 100 zu 5 % werden nach einem Jahr zu 105 und nach zwei Jahren zu 110,25.', 'Procent składany to odsetki naliczane od wcześniejszych odsetek: 100 zł przy 5% rocznie daje 105 zł po roku i 110,25 zł po dwóch latach.', 'https://www.investor.gov/additional-resources/information/youth/teachers-classroom-resources/what-compound-interest'),
  ('interest', 5, 'Same compounding example with a yearly calculation: start with 1,000 at 5%, then 1,050 after year one and 1,102.50 after year two.', 'Beispiel für jährliche Verzinsung: 1.000 zu 5 % ergeben 1.050 nach Jahr eins und 1.102,50 nach Jahr zwei.', 'Przykład kapitalizacji: 1 000 zł przy 5% to 1 050 zł po pierwszym roku i 1 102,50 zł po drugim roku.', 'https://www.consumerfinance.gov/ask-cfpb/how-does-compound-interest-work-en-1683/'),
  ('interest', 6, 'In Germany, a Freistellungsauftrag allows earning up to 1,000 EUR in capital gains tax-free. In Poland, capital gains are taxed under the 19% Belka tax.', 'In Deutschland ermöglicht ein Freistellungsauftrag bis zu 1.000 Euro steuerfreie Kapitalerträge pro Person.', 'W Polsce zyski kapitałowe (w tym odsetki od lokat i rachunków) podlegają 19% zryczałtowanemu podatkowi dochodowemu (tzw. podatek Belki).', 'https://verwaltung.bund.de/leistungsverzeichnis/de/leistung/99102040010000/herausgeber/RP-229931708/region/070000000000'),
  ('interest', 7, 'Statutory requirements require lenders to disclose the effective annual interest rate (e.g. APR, RRSO, effektiver Jahreszins) including all mandatory credit fees.', 'Kreditgeber sind gesetzlich verpflichtet, den effektiven Jahreszins einschließlich aller Nebenkosten auszuweisen.', 'Instytucje finansowe mają obowiązek podawania Rzeczywistej Rocznej Stopy Oprocentowania (RRSO) uwzględniającej wszystkie koszty kredytu.', 'https://www.bundesbank.de/de/service/schule-und-bildung/erklaerfilme/was-sind-zinsen--860012'),
  ('taxes', 0, 'Legally, taxes are money payments that are not a payment for a particular service in return, and that a public body charges everyone who meets the conditions set in the law.', 'Rechtlich sind Steuern Geldleistungen ohne Gegenleistung für eine besondere Leistung, die ein öffentlich-rechtliches Gemeinwesen allen auferlegt.', 'Prawnie podatki to nieodpłatne, przymusowe oraz bezzwrotne świadczenia pieniężne na rzecz państwa lub samorządu terytorialnego.', 'https://www.gesetze-im-internet.de/ao_1977/__3.html'),
  ('taxes', 1, 'Taxes are the state''s most important source of income, and the money pays for shared tasks such as education, health, transport infrastructure and security.', 'Steuern sind die wichtigste Einnahmequelle des Staates für Bildung, Gesundheit, Verkehrswege und Sicherheit.', 'Podatki stanowią główne źródło dochodów państwa, finansując edukację, służbę zdrowia, drogi oraz bezpieczeństwo publiczne.', 'https://www.bundesfinanzministerium.de/Content/DE/Standardartikel/Themen/Steuern/steuern.html'),
  ('taxes', 2, 'The state builds hospitals, schools and roads with tax money, and pays public servants such as police officers and firefighters.', 'Mit Steuergeldern baut der Staat Krankenhäuser, Schulen und Straßen und bezahlt Polizei und Feuerwehr.', 'Z podatków państwo buduje szpitale, szkoły i drogi oraz opłaca policjantów i strażaków.', 'https://www.bundesfinanzministerium.de/Content/DE/Standardartikel/Service/Leichte_Sprache/steuern.html'),
  ('taxes', 3, 'Progressive taxation means that higher earners pay a higher proportion of their income in taxes.', 'Steuerprogression bedeutet, dass höhere Einkommen mit einem höheren Steuersatz besteuert werden.', 'Progresja podatkowa oznacza, że osoby o wyższych dochodach płacą wyższą stawkę podatkową.', 'https://www.bundesfinanzministerium.de/Content/DE/Standardartikel/Service/Leichte_Sprache/steuern.html'),
  ('taxes', 4, 'Employers deduct wage taxes automatically from monthly earnings and remit them to the tax authorities.', 'Arbeitgeber behalten die Lohnsteuer direkt vom Gehalt ein und führen sie an das Finanzamt ab.', 'Pracodawcy potrącają zaliczki na podatek dochodowy bezpośrednio z wynagrodzenia pracownika i przekazują je do urzędu skarbowego.', 'https://esth.bundesfinanzministerium.de/lsth/2026/A-Einkommensteuergesetz/VI-Steuererhebung-36-47/2-Steuerabzug-vom-Arbeitslohn-Lohnsteuer-38-42g/Paragraf-38/paragraf-38.html'),
  ('taxes', 5, 'Tax administrations offer electronic platforms (such as ELSTER in Germany, Twój e-PIT in Poland, or e-Filing in India) to file tax returns online.', 'Finanzverwaltungen bieten elektronische Portale (z. B. ELSTER in Deutschland) zur Übermittlung von Steuererklärungen an.', 'Urzędy skarbowe udostępniają platformy elektroniczne (np. Twój e-PIT w Polsce, ELSTER w Niemczech) do składania deklaracji przez internet.', 'https://www.finanzamt.nrw.de/elster-ihr-online-finanzamt'),
  ('taxes', 6, 'Tax decisions in democratic societies are made by elected representatives in municipal councils and national parliaments.', 'In der Demokratie werden Steuergesetze von gewählten Vertretern in Gemeinderäten und Parlamenten beschlossen.', 'W państwach demokratycznych decyzje podatkowe podejmują wybierani przedstawiciele w radach gmin i w parlamencie.', 'https://www.gesetze-im-internet.de/gg/art_20.html'),
  ('inflation', 0, 'Inflation means a persistent rise in the general price level. The inflation rate is the percentage by which the price level rose over a period. Inflation lowers the purchasing power of money.', 'Inflation bezeichnet einen dauerhaften Anstieg des allgemeinen Preisniveaus und mindert die Kaufkraft des Geldes.', 'Inflacja to trwały wzrost ogólnego poziomu cen w gospodarce, oznaczający spadek siły nabywczej pieniądza.', 'https://www.bundesbank.de/en/bundesbank/research/survey-on-consumer-expectations-bop-hh/background-information-850064'),
  ('inflation', 1, 'High inflation means money loses purchasing power: income and savings buy less than before.', 'Hohe Inflation schwächt die Kaufkraft von Einkommen und Ersparnissen merklich.', 'Wysoka inflacja oznacza utratę siły nabywczej: za dochody i oszczędności można kupić mniej dóbr niż wcześniej.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/stableprices.en.html'),
  ('inflation', 2, 'Inflation can be driven by strong demand (demand-pull) or by rising production costs (cost-push).', 'Inflation kann durch hohe Nachfrage (Demand-Pull) oder gestiegene Produktionskosten (Cost-Push) ausgelöst werden.', 'Inflacja może wynikać z nadmiernego popytu (inflacja popytowa) lub rosnących kosztów produkcji (inflacja kosztowa).', 'https://www.clevelandfed.org/center-for-inflation-research/inflation-explained-your-guide-to-inflation-basics/what-causes-inflation'),
  ('inflation', 3, 'Real interest is nominal interest minus inflation; if interest is below inflation, savings lose purchasing power.', 'Der Realzins ist der Zins abzüglich der Inflationsrate; liegt der Zins unter der Inflation, verlieren Ersparnisse an Kaufkraft.', 'Realna stopa procentowa to oprocentowanie nominalne pomniejszone o inflację; gdy odsetki są niższe od inflacji, oszczędności tracą wartość.', 'https://www.bundesbank.de/de/statistiken/geld-und-kapitalmaerkte/zinssaetze-und-renditen/realzinssaetze-auf-bankeinlagen/realzinssaetze-auf-bankeinlagen-772412'),
  ('inflation', 4, 'Deflation (falling price level) can cause businesses to postpone investments and lay off workers, triggering an economic slump.', 'Deflation (sinkendes Preisniveau) kann zu Konsumaufschub, sinkenden Unternehmensgewinnen und Entlassungen führen.', 'Deflacja (spadek poziomu cen) prowadzi do odkładania zakupów, spadku zysków firm i zwolnień pracowników.', 'https://www.bundesbank.de/en/service/school-service/animation-videos/price-stability-860064'),
  ('inflation', 5, 'National statistical offices (like GUS in Poland, Destatis in Germany, MOSPI in India) measure the Consumer Price Index monthly.', 'Statistische Ämter messen monatlich den Verbraucherpreisindex anhand eines repräsentativen Warenkorbs.', 'Główny Urząd Statystyczny (GUS) bada co miesiąc wskaźnik cen towarów i usług konsumpcyjnych (CPI) na podstawie koszyka zakupowego.', 'https://www.destatis.de/DE/Themen/Wirtschaft/Preise/Verbraucherpreisindex/_inhalt.html'),
  ('inflation', 6, 'Central banks aim for moderate, predictable inflation (e.g. 2% for ECB, 2.5% for NBP, 4% for RBI) to ensure price stability.', 'Zentralbanken streben mittelfristig eine moderate Inflation von etwa 2 % an, um Preisstabilität zu sichern.', 'Banki centralne dbają o stabilność cen, dążąc do celu inflacyjnego (np. 2,5% dla NBP, 2% dla EBC).', 'https://www.ecb.europa.eu/mopo/strategy/pricestab/html/index.en.html'),
  ('printing', 0, 'Inflation is a broad increase in the prices of goods and services: you can buy less for 1 euro today than yesterday, so inflation reduces the value of the currency.', 'Inflation ist ein breit angelegter Anstieg der Preise von Waren und Dienstleistungen, der den Wert der Währung mindert.', 'Inflacja to powszechny wzrost cen towarów i usług, który obniża wartość i siłę nabywczą waluty.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/what_is_inflation.en.html'),
  ('printing', 1, 'In 1923 the German government borrowed from the Reichsbank, which printed more and more banknotes. This was not matched by growth in the supply of goods, so huge price increases resulted.', '1923 druckte die Reichsbank immer mehr Banknoten ohne entsprechendes Güterwachstum, was zu enormen Preissteigerungen führte.', 'W 1923 roku rząd niemiecki pożyczał od Reichsbanku, który drukował masowo banknoty bez pokrycia w towarach, wywołując hiperinflację.', 'https://www.bundesbank.de/en/tasks/topics/inflation-lessons-learnt-from-history-666006'),
  ('printing', 2, 'The nominal price of a loaf of bread in Germany was 0.80 Mark in December 1919 and 201 billion Mark in November 1923. Workers collected their pay in sacks and rushed to spend it.', 'Der Brotpreis stieg in Deutschland von 0,80 Mark (1919) auf 201 Milliarden Mark (November 1923). Löhne wurden teils mit Schubkarren abgeholt.', 'Cena bochenka chleba w Niemczech wzrosła z 0,80 marki w 1919 roku do 201 miliardów marek w listopadzie 1923 roku.', 'https://www.bundestag.de/parlament/geschichte/100-jahre-weimar/hyperinflation-970722'),
  ('printing', 3, 'Article 123 of the Treaty on the Functioning of the European Union prohibits central banks from directly financing governments and public bodies.', 'Artikel 123 des AEU-Vertrags verbietet der EZB und nationalen Zentralbanken die direkte Finanzierung staatlicher Haushalte.', 'Artykuł 123 Traktatu o funkcjonowaniu Unii Europejskiej zabrania bankom centralnym bezpośredniego finansowania instytucji publicznych.', 'https://eur-lex.europa.eu/eli/treaty/tfeu_2016/art_123/oj/eng'),
  ('printing', 4, 'Article 220, paragraph 2 of the Polish Constitution prohibits financing the state budget deficit by borrowing from the central bank (NBP).', 'Artikel 220 der polnischen Verfassung verbietet die Deckung des Haushaltsdefizits durch Kredite bei der Zentralbank.', 'Artykuł 220 ust. 2 Konstytucji Rzeczypospolitej Polskiej zabrania pokrywania deficytu budżetowego przez zaciąganie zobowiązań w centralnym banku państwa.', 'https://www.sejm.gov.pl/prawo/konst/polski/kon1.htm'),
  ('printing', 5, 'The primary objective of central banks (such as ECB, NBP, and RBI) is price stability, and independence protects them from political pressure to print money.', 'Hauptziel unabhängiger Zentralbanken ist die Preisstabilität, geschützt vor politischem Druck zur Geldschöpfung.', 'Głównym celem niezależnych banków centralnych (jak NBP czy EBC) jest utrzymanie stabilności cen.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/five_things.en.html'),
  ('rates', 0, 'The ECB is the central bank for the euro, and the Bundesbank participates in its decisions; its main objective is price stability.', 'Die EZB ist die Zentralbank für den Euro; ihr vorrangiges Ziel ist die Gewährleistung von Preisstabilität im Euroraum.', 'Narodowy Bank Polski (NBP) wraz z Radą Polityki Pieniężnej (RPP) odpowiada za stabilność polskiego złotego i poziom stóp procentowych.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/five_things.en.html'),
  ('rates', 1, 'The central bank sets key policy rates (such as the repo rate or deposit facility rate), which influence bank lending rates and deposit rates across the economy.', 'Die Zentralbank legt die Leitzinsen fest, an denen sich die Kreditzinsen und Sparzinsen der Geschäftsbanken orientieren.', 'Bank centralny ustala stopy referencyjne, które wyznaczają poziom oprocentowania kredytów i depozytów w bankach komercyjnych.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/html/interest-rates-changes.en.html'),
  ('rates', 2, 'Raising interest rates cools demand and lowers inflation, while cutting rates stimulates borrowing, spending, and economic activity.', 'Höhere Leitzinsen dämpfen die Nachfrage und bremsen die Inflation; Zinssenkungen kurbeln Investitionen und Konsum an.', 'Podwyżka stóp chłodzi popyt i tłumi inflację, a obniżka pobudza akcję kredytową i ożywia gospodarkę.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/five_things.en.html'),
  ('rates', 3, 'Monetary policy transmission works with long and variable time lags: it can take several quarters for rate adjustments to fully affect inflation.', 'Die geldpolitische Transmission wirkt mit langen und variablen zeitlichen Verzögerungen.', 'Oddziaływanie polityki pieniężnej na gospodarkę cechuje się długimi opóźnieniami czasowymi sięgającymi kilku kwartałów.', 'https://www.ecb.europa.eu/mopo/intro/transmission/html/index.en.html'),
  ('rates', 4, 'Central banks aim for moderate inflation (e.g. 2% for ECB, 2.5% for NBP, 4% for RBI), avoiding both harmful inflation and destructive deflation.', 'Zentralbanken streben eine moderate Zielinflation an, um sowohl Inflation als auch Deflationsspiralen zu verhindern.', 'Banki centralne dążą do umiarkowanego celu inflacyjnego (np. 2,5% dla NBP, 2% dla EBC), zapobiegając zarówno wysokiej inflacji, jak i deflacji.', 'https://www.ecb.europa.eu/mopo/strategy/pricestab/html/index.en.html'),
  ('profit', 0, 'In business accounting, profit is the positive difference between earnings (revenue) and expenses (costs) over a given period.', 'Im Rechnungswesen ist Gewinn der positive Unterschiedsbetrag zwischen Erträgen und Aufwendungen einer Periode.', 'W rachunkowości zysk to dodatnia różnica między przychodami a kosztami ich uzyskania w danym okresie.', 'https://wirtschaftslexikon.gabler.de/definition/gewinn-33630'),
  ('profit', 1, 'Under the Polish Accounting Act (Ustawa o rachunkowości) and German Commercial Code (HGB), businesses must account for all revenues and operating expenses in an income statement.', 'Das Handelsgesetzbuch (HGB) verlangt von Kaufleuten eine Gewinn- und Verlustrechnung, die Aufwendungen und Erträge gegenüberstellt.', 'Ustawa o rachunkowości nakłada obowiązek sporządzania rachunku zysków i strat, który zestawia przychody i koszty przedsiębiorstwa.', 'https://www.gesetze-im-internet.de/hgb/__242.html'),
  ('profit', 2, 'Official statistics show how raw material prices (flour, grain) and energy costs directly determine product pricing in craft bakeries.', 'Statistische Ämter erfassen Erzeuger- und Verbraucherpreise, um den Einfluss von Energie- und Rohstoffkosten auf Endpreise zu zeigen.', 'Główny Urząd Statystyczny (GUS) bada wskaźniki cen produkcji, obrazując wpływ kosztów surowców i energii na ceny pieczywa.', 'https://www.destatis.de/DE/Themen/Wirtschaft/Preise/_inhalt.html'),
  ('profit', 3, 'Central banks and economic institutions note that sustainable enterprises must cover costs and earn sufficient profit to reinvest in equipment and weather downturns.', 'Wirtschaftsinstitute betonen, dass nachhaltige Unternehmen Gewinne erwirtschaften müssen, um Investitionen zu tätigen und Krisen zu überstehen.', 'Ekonomiści wskazują, że stabilne firmy muszą generować zysk, aby inwestować w rozwój i tworzyć poduszkę finansową.', 'https://www.ecb.europa.eu/ecb/educational/html/index.en.html'),
  ('profit', 4, 'Trade associations note that craft bakeries calculate prices to cover raw ingredients, energy for high-temperature ovens, staff wages, and lease expenses.', 'Das Bäckerhandwerk kalkuliert Preise so, dass Rohstoffe, Energie für Backöfen, Personallöhne und Pachtkosten gedeckt sind.', 'Związki rzemieślnicze wskazują, że piekarnie kalkulują ceny tak, by pokryć surowce, prąd do pieców, płace personelu i koszty najmu.', 'https://www.baeckerhandwerk.de/'),
  ('sales', 0, 'Official statistical offices track monthly retail sales as a core indicator of economic strength and consumer demand.', 'Statistische Ämter erfassen den monatlichen Einzelhandelsumsatz als zentralen Maßstab für Wirtschaftsleistung und Konsumnachfrage.', 'Główny Urząd Statystyczny (GUS) publikuje miesięczne dane o sprzedaży detalicznej jako kluczowy wskaźnik koniunktury i popytu konsumentów.', 'https://www.destatis.de/DE/Themen/Wirtschaft/Grosshandel-Einzelhandel/_inhalt.html'),
  ('sales', 1, 'Economic ministries emphasize that consistent customer demand and sales volume are vital for small trade and craft businesses.', 'Wirtschaftsministerien heben hervor, dass stetige Kundennachfrage und Umsätze das Fundament für mittelständische Betriebe bilden.', 'Ministerstwo Rozwoju i Technologii wskazuje, że popyt rynkowy i stała sprzedaż są niezbędne dla stabilności mikroprzedsiębiorstw i rzemiosła.', 'https://www.bmwk.de/Redaktion/DE/Dossier/mittelstand.html'),
  ('sales', 2, 'National retail federations represent enterprises that link primary producers and manufacturers directly to retail shoppers.', 'Handelsverbände vertreten Einzelhandelsunternehmen, die Erzeuger und Verbraucher auf Marktplätzen und in Geschäften verbinden.', 'Polska Izba Handlu reprezentuje przedsiębiorców handlowych, łączących lokalnych producentów i rolników z konsumentami.', 'https://einzelhandel.de/'),
  ('sales', 3, 'Chambers of commerce provide guidance on customer service, pricing transparency, and building repeat business.', 'Industrie- und Handelskammern bieten Leitfäden für Kundenorientierung, Preisauszeichnung und langfristige Kundenbindung an.', 'Krajowa Izba Gospodarcza podkreśla wagę przejrzystości cenowej, zaufania konsumentów i budowania lojalności klientów.', 'https://www.dihk.de/'),
  ('sales', 4, 'Tax administrations require commercial sellers to record all individual sales transactions using certified cash registers or receipts.', 'Die Finanzverwaltung verlangt von gewerblichen Verkäufern eine ordnungsgemäße Einzelaufzeichnung aller Verkaufsvorgänge über Kassensysteme.', 'Krajowa Administracja Skarbowa (KAS) wymaga ewidencjonowania każdej sprzedaży na rzecz konsumentów za pomocą kas fiskalnych.', 'https://www.bundesfinanzministerium.de/'),
  ('ticketsize', 0, 'Central banking and economic research explain how commercial enterprises balance price per transaction and transaction volume to reach their revenue targets.', 'Zentralbanken und Wirtschaftsforschungsinstitute erklären, wie Unternehmen Ticketgröße und Transaktionsvolumen steuern, um Umsatzziele zu erreichen.', 'Ekonomiści i analitycy rynku wyjaśniają, jak przedsiębiorstwa równoważą cenę jednostkową z wolumenem sprzedaży, aby zrealizować plan przychodów.', 'https://www.bundesbank.de/de/service/schule-und-bildung'),
  ('ticketsize', 1, 'Antitrust and competition authorities analyze market structures, contrasting high-frequency grocery retail with durable goods and bespoke manufacturing.', 'Kartell- und Wettbewerbsbehörden untersuchen Marktstrukturen und vergleichen hochfrequenten Einzelhandel mit langlebigen Investitionsgütern.', 'Urzędy ochrony konkurencji (UOKiK) badają rynki, odróżniając handel artykułami częstego zakupu od rynków dóbr trwałego użytku.', 'https://www.bundeskartellamt.de/DE/Wirtschaftsbereiche/Handel/handel_node.html'),
  ('ticketsize', 2, 'Economic research institutes study structural differences between fast-moving mass consumer goods (FMCG) and craft or luxury goods.', 'Wirtschaftsinstitute analysieren strukturelle Unterschiede zwischen schnelldrehenden Konsumgütern und maßgefertigtem Handwerk.', 'Instytuty badań rynkowych analizują różnice między produktami szybkozbywalnymi (FMCG) a produkcją rzemieślniczą i dobrami luksusowymi.', 'https://www.iwkoeln.de/'),
  ('ticketsize', 3, 'Statistical bureaus record consumer spending across frequent small-ticket grocery purchases and periodic major household durable investments.', 'Statistische Ämter erfassen Konsumausgaben sowohl für alltägliche Kleinbeträge als auch für seltene, größere Anschaffungen.', 'Główny Urząd Statystyczny (GUS) bada wydatki gospodarstw domowych, dzieląc je na codzienne zakupy żywności oraz rzadkie zakupy dóbr trwałych.', 'https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Einkommen-Konsum-Lebensbedingungen/Konsumausgaben/_inhalt.html'),
  ('ticketsize', 4, 'Retail federations report that operating margins and stock turnover rates differ drastically between high-volume, low-margin food retail and low-volume, high-margin specialty shops.', 'Handelsverbände belegen, dass Handelsspannen und Lagerumschlag zwischen Massengütern und margenstarken Spezialgeschäften stark variieren.', 'Izby handlowe wskazują, że marże handlowe oraz rotacja zapasów diametralnie różnią się między dyskontami a sklepami specjalistycznymi.', 'https://einzelhandel.de/presse/zahlen-fakten'),
  ('marketshare', 0, 'Antitrust and competition regulators conduct merger control and abuse of dominance investigations based on enterprise market shares.', 'Kartellbehörden führen Fusionskontrollen und Untersuchungen zu marktbeherrschenden Stellungen anhand von Marktanteilen durch.', 'Urzędy antymonopolowe (takie jak UOKiK) prowadzą kontrolę koncentracji przedsiębiorstw i badają pozycję dominującą na podstawie udziałów w rynku.', 'https://www.bundeskartellamt.de/DE/Fusionskontrolle/fusionskontrolle_node.html'),
  ('marketshare', 1, 'Independent monopoly commissions publish regular reports examining concentration across retail, food, and energy sectors.', 'Unabhängige Monopolkommissionen veröffentlichen Hauptgutachten zur Marktkonzentration im Einzelhandel und Energiesektor.', 'Niezależne instytucje i urzędy publikują raporty badające poziom koncentracji i stan konkurencji w handlu detalicznym oraz energetyce.', 'https://www.monopolkommission.de/'),
  ('marketshare', 2, 'In economics, market share denotes the percentage of total sales or unit volume in an industry earned by a specific firm.', 'In der Wirtschaftswissenschaft bezeichnet der Marktanteil den prozentualen Anteil eines Unternehmens am gesamten Marktvolumen.', 'W ekonomii udział w rynku oznacza procentowy udział danego przedsiębiorstwa w całkowitej sprzedaży lub wolumenie całej branży.', 'https://wirtschaftslexikon.gabler.de/definition/marktanteil-39049'),
  ('marketshare', 3, 'Regulatory enforcement activity documents actions preventing excessive concentration in regional consumer goods markets.', 'Tätigkeitsberichte der Aufsichtsbehörden dokumentieren Maßnahmen gegen übermäßige Marktmacht auf regionalen Konsumgütermärkten.', 'Sprawozdania organów regulacyjnych dokumentują działania chroniące otwarty rynek i zapobiegające powstawaniu monopoli w handlu detalicznym.', 'https://www.bundeskartellamt.de/DE/UeberUns/Jahresbericht/jahresbericht_node.html'),
  ('marketshare', 4, 'Economic ministries maintain competition policy frameworks to protect open markets, spur innovation, and safeguard consumer choice.', 'Wirtschaftsministerien gestalten die Wettbewerbspolitik, um offene Märkte, Innovationen und Wahlfreiheit für Verbraucher zu sichern.', 'Ministerstwa gospodarki i urzędy państwowe realizują politykę ochrony konkurencji, wspierając innowacje i swobodę wyboru konsumentów.', 'https://www.bmwk.de/Redaktion/DE/Dossier/wettbewerbspolitik.html'),
  ('competition', 0, 'The Competition Act, 2002 and antitrust laws like Germany''s GWB establish the legal framework prohibiting anti-competitive agreements and cartel formation.', 'Das Gesetz gegen Wettbewerbsbeschränkungen (GWB) bildet das rechtliche Fundament zur Sicherung des fairen wirtschaftlichen Wettbewerbs.', 'Ustawa o ochronie konkurencji i konsumentów stanowi fundament prawny chroniący wolny rynek przed niedozwolonymi porozumieniami i kartelami.', 'https://uokik.gov.pl/ochrona_konkurencji.php'),
  ('competition', 1, 'Competition authorities actively investigate and penalize illegal price-fixing cartels to protect consumers from inflated prices.', 'Das Bundeskartellamt verfolgt illegale Kartelle und Preisabsprachen konsequent, um Verbraucher vor überhöhten Preisen zu schützen.', 'UOKiK konsekwentnie wykrywa i karze nielegalne kartele oraz zmowy cenowe, chroniąc konsumentów przed sztucznie zawyżanymi cenami.', 'https://uokik.gov.pl/zmowy_cenowe.php'),
  ('competition', 2, 'The European Commission enforces antitrust directives across the European single market, fostering cross-border innovation and consumer welfare.', 'Die Europäische Kommission setzt Wettbewerbsregeln im EU-Binnenmarkt durch, um Marktöffnung und Innovation zu fördern.', 'Komisja Europejska egzekwuje unijne reguły konkurencji na jednolitym rynku europejskim, wspierając innowacje i dobrobyt konsumentów.', 'https://competition-policy.ec.europa.eu/index_en'),
  ('competition', 3, 'Economic ministries and regulatory agencies safeguard competitive market structures so enterprise efficiency benefits households directly.', 'Wirtschaftsministerien gestalten die Rahmenbedingungen so, dass unternehmerische Effizienz durch Wettbewerb bei den Bürgern ankommt.', 'Ministerstwa gospodarki oraz organy regulacyjne dbają o to, by korzyści z efektywności i konkurencji przedsiębiorstw trafiały do gospodarstw domowych.', 'https://www.bmwk.de/Redaktion/DE/Dossier/wettbewerbspolitik.html'),
  ('competition', 4, 'Economic foundations and research institutes demonstrate that fair market competition is the primary driver of quality improvements and broad prosperity.', 'Wirtschaftswissenschaftliche Institute belegen, dass offener Wettbewerb der wesentliche Motor für Qualitätsverbesserungen und Wohlstand ist.', 'Instytuty ekonomiczne dowodzą, że otwarta i uczciwa konkurencja stanowi główny motor podnoszenia jakości towarów oraz powszechnego dobrobytu.', 'https://www.ludwig-erhard.de/'),
  ('marketing', 0, 'Consumer protection and unfair competition laws strictly prohibit misleading advertising and unsubstantiated product claims.', 'Das Gesetz gegen den unlauteren Wettbewerb (UWG) verbietet irreführende geschäftliche Handlungen und falsche Werbeversprechen.', 'Ustawa o zwalczaniu nieuczciwej konkurencji oraz ustawa o przeciwdziałaniu nieuczciwym praktykom rynkowym zabraniają wprowadzania w błąd w reklamie.', 'https://uokik.gov.pl/nieuczciwe_praktyki_rynkowe.php'),
  ('marketing', 1, 'Advertising standards self-regulatory bodies investigate public complaints regarding misleading or inappropriate commercial campaigns.', 'Der Deutsche Werberat prüft als Selbstkontrollorgan Beschwerden von Bürgern über unangemessene oder irreführende Werbung.', 'Rada Reklamy i Komisja Etyki Reklamy rozpatrują skargi konsumentów na nieetyczne lub wprowadzające w błąd kampanie promocyjne.', 'https://radareklamy.pl/'),
  ('marketing', 2, 'Digital economy associations publish guidance on influencer transparency, sponsored disclosures, and clear commercial identifiers.', 'Branchenverbände der Digitalwirtschaft veröffentlichen Leitfäden zu Kennzeichnungspflichten und Transparenz im Online-Marketing.', 'Związki branży cyfrowej (takie jak IAB Polska) wydają standardy i wytyczne dotyczące transparentnego oznaczania reklam i influencer marketingu.', 'https://iab.org.pl/'),
  ('marketing', 3, 'Chambers of Commerce advise entrepreneurs on consumer rights, truthful pricing disclosures, and fair competitive conduct.', 'Industrie- und Handelskammern (IHK) beraten Gewerbetreibende zu rechtssicherem Marketing und fairem Wettbewerbsverhalten.', 'Izby gospodarcze i organizacje przedsiębiorców doradzają firmom w zakresie praw konsumenta i zgodnego z prawem marketingu.', 'https://kig.pl/'),
  ('marketing', 4, 'In marketing economics, advertising serves an information-sharing function that reduces consumer search costs when kept truthful.', 'In der Volkswirtschaft erfüllt ehrliche Werbung eine Informationsfunktion, die Suchkosten für Verbraucher senkt.', 'W ekonomii rzetelna reklama pełni funkcję informacyjną, obniżając koszty poszukiwania towarów przez konsumentów.', 'https://wirtschaftslexikon.gabler.de/definition/werbung-49591'),
  ('hiring', 0, 'Labor ministries oversee the statutory minimum wage regulations ensuring fair guaranteed compensation for working time.', 'Das Bundesministerium für Arbeit und Soziales überwacht den gesetzlichen Mindestlohn zur Sicherung angemessener Mindestentgelte.', 'Ministerstwo Rodziny, Pracy i Polityki Społecznej ustala ustawowe wynagrodzenie minimalne, gwarantując minimalną stawkę za pracę.', 'https://www.gov.pl/web/rodzina/minimalne-wynagrodzenie-za-prace'),
  ('hiring', 1, 'Labor courts and statutory labor codes establish established jurisprudence placing economic and operational business risk on employers.', 'Das Bundesarbeitsgericht weist das Betriebs- und Wirtschaftsrisiko der Unternehmensführung rechtlich den Arbeitgebern zu.', 'Kodeks pracy (art. 81) i orzecznictwo Sądu Najwyższego obciążają pracodawcę ryzykiem gospodarczym, nakazując wypłatę pensji za czas przestoju.', 'https://sip.lex.pl/akty-prawne/dzu-dziennik-ustaw/kodeks-pracy-16785942/art-81'),
  ('hiring', 2, 'Labor research institutes study employment creation, minimum wage effects, and enterprise labor liquidity across the economy.', 'Das Institut für Arbeitsmarkt- und Berufsforschung (IAB) untersucht Beschäftigungseffekte, Lohnentwicklungen und unternehmerische Liquidität.', 'Instytut Badań Strukturalnych (IBS) bada tworzenie miejsc pracy, wpływ płacy minimalnej oraz stabilność zatrudnienia w gospodarce.', 'https://ibs.org.pl/'),
  ('hiring', 3, 'Public development and enterprise agencies advise small businesses on maintaining liquidity cushions against seasonal downswings.', 'Die Förderbank KfW überwacht im Mittelstandspanel Liquiditätspuffer und Beschäftigungspläne kleiner Unternehmen.', 'Polska Agencja Rozwoju Przedsiębiorczości (PARP) doradza małym i średnim firmom w zakresie zarządzania płynnością finansową i buforami rezerwowymi.', 'https://www.parp.gov.pl/'),
  ('hiring', 4, 'Central banking authorities monitor business savings and liquidity buffers maintained by firms to withstand cyclical contractions.', 'Die Deutsche Bundesbank analysiert die Ersparnisse und Liquiditätsreserven der Unternehmen zur Krisenbewältigung.', 'Narodowy Bank Polski (NBP) monitoruje kondycję finansową sektora przedsiębiorstw oraz rezerwy płynnościowe firm na wypadek kryzysu.', 'https://nbp.pl/publikacje/materialy-i-studia/'),
  ('scale', 0, 'Enterprise research institutes define and document the economic contribution and employment share of small and medium enterprises (SMEs).', 'Das Institut für Mittelstandsforschung (IfM Bonn) dokumentiert den Beitrag und die Beschäftigungskraft kleiner und mittlerer Unternehmen.', 'Polska Agencja Rozwoju Przedsiębiorczości (PARP) analizuje w corocznych raportach wkład sektora MŚP w tworzenie miejsc pracy i polskie PKB.', 'https://www.parp.gov.pl/storage/publications/pdf/Raport_o_stanie_sektora_MSP_w_Polsce.pdf'),
  ('scale', 1, 'National statistical offices categorize business activity across micro-enterprises, small firms, and large industrial manufacturers.', 'Das Statistische Bundesamt (Destatis) erfasst Unternehmensregister nach Größenklassen von Kleinstbetrieben bis zu Industrieunternehmen.', 'Główny Urząd Statystyczny (GUS) klasyfikuje podmioty gospodarcze w rejestrze REGON od mikroprzedsiębiorstw po wielkie zakłady przemysłowe.', 'https://stat.gov.pl/obszary-tematyczne/podmioty-gospodarcze-wyniki-finansowe/przedsiebiorstwa-niefinansowe/'),
  ('scale', 2, 'Economic and development ministries establish structural policy frameworks supporting agile artisan businesses alongside industrial manufacturing scale.', 'Wirtschaftsministerien gestalten Rahmenbedingungen zur Förderung innovativer mittelständischer Betriebe und industrieller Großserien.', 'Ministerstwo Rozwoju i Technologii tworzy ramy prawne i programy wspierające rzemiosło oraz rozwój nowoczesnego przemysłu w Polsce.', 'https://www.gov.pl/web/rozwoj-technologia/przedsiebiorcy'),
  ('scale', 3, 'Industry confederations represent manufacturers achieving economies of scale through automation, robotics, and integrated supply networks.', 'Industrieverbände (BDI) vertreten produzierende Großunternehmen, die durch Automatisierung und Fabriken globale Größenvorteile erzielen.', 'Konfederacja Lewiatan reprezentuje zakłady produkcyjne osiągające korzyści skali dzięki automatyzacji i integracji łańcuchów dostaw.', 'https://fcpp.org.pl/'),
  ('scale', 4, 'Chambers of Craft and Commerce highlight the complementary economic roles of bespoke regional craftsmanship and automated mass production.', 'Handwerkskammern und Industrie- und Handelskammern betonen das Zusammenwirken von lokalem Maßhandwerk und industrieller Serienfertigung.', 'Związek Rzemiosła Polskiego podkreśla kluczową rolę rzemiosła i usług na zamówienie uzupełniających zautomatyzowaną produkcję seryjną.', 'https://zrp.pl/'),
  ('supplydemand', 0, 'The market clearing price forms at the intersection of supply and demand schedules where available quantity matches buyer demand.', 'Der markträumende Preis bildet sich im Schnittpunkt von Angebot und Nachfrage, wo die gehandelte Menge geräumt wird.', 'Cena równowagi rynkowej ustala się w punkcie przecięcia krzywych popytu i podaży, oczyszczając rynek z nadwyżek i niedoborów.', 'https://stat.gov.pl/metainformacje/slownik-pojec/pojecia-stosowane-w-statystyce-publicznej/2753,pojecie.html'),
  ('supplydemand', 1, 'Agricultural produce market committees and commodity trading platforms continuously match bids and offers to establish transparent spot prices.', 'Moderne Handelsplätze führen Kauf- und Verkaufsaufträge kontinuierlich zusammen, um transparente Referenzpreise zu ermitteln.', 'Towarowa Giełda Energii (TGE) oraz giełdy rolne łączą zlecenia kupna i sprzedaży, wyznaczając przejrzyste ceny referencyjne.', 'https://www.tge.pl/'),
  ('supplydemand', 2, 'Central banking and competition authorities recognize price discovery as essential for guiding efficient resource allocation across the economy.', 'Notenbanken und Kartellbehörden betonen Preissignale als unverzichtbaren Mechanismus zur optimalen volkswirtschaftlichen Ressourcenlenkung.', 'Narodowy Bank Polski i Urząd Ochrony Konkurencji i Konsumentów (UOKiK) uznają mechanizm cenowy za kluczowy dla efektywnej alokacji zasobów.', 'https://nbp.pl/edukacja/'),
  ('supplydemand', 3, 'National statistical agencies systematically record producer and consumer price variations across wholesale markets and grocery baskets.', 'Das Statistische Bundesamt (Destatis) misst Erzeuger- und Verbraucherpreisschwankungen über Tausende Güter hinweg.', 'Główny Urząd Statystyczny (GUS) monitoruje notowania cen na targowiskach i w sklepach, badając dynamikę cen koszyka żywnościowego.', 'https://stat.gov.pl/obszary-tematyczne/ceny-handel/'),
  ('supplydemand', 4, 'Antitrust regulations prohibit artificial hoarding and price manipulation to preserve natural competitive supply and demand forces.', 'Wettbewerbsbehörden (Bundeskartellamt) verbieten künstliche Verknappung und Preisabsprachen zur Wahrung des freien Marktes.', 'Ustawa o ochronie konkurencji i konsumentów zabrania zmów cenowych i sztucznego ograniczania podaży przez monopolistów.', 'https://uokik.gov.pl/ochrona-konkurencji'),
  ('commodities', 0, 'Commodities are standardized, fungible raw materials traded on specialized exchanges without individual brand differentiation.', 'Rohstoffe sind standardisierte, austauschbare Grundstoffe, die an spezialisierten Warenbörsen ohne Markenunterschiede gehandelt werden.', 'Towary masowe (surowce) to ustandaryzowane, zamienne dobra podstawowe handlowane na wyspecjalizowanych giełdach bez względu na markę producenta.', 'https://www.tge.pl/slownik-pojec'),
  ('commodities', 1, 'Agricultural commodity prices experience high volatility driven by seasonal climatic variations, crop yields, and rainfall distribution.', 'Agrarrohstoffpreise unterliegen starken Schwankungen durch Witterungsverläufe, Erntemengen und saisonale Wetterereignisse.', 'Ceny surowców rolnych cechują się wysoką zmiennością wynikającą z warunków pogodowych, suszy oraz wielkości zbiorów raportowanych przez GUS.', 'https://stat.gov.pl/obszary-tematyczne/rolnictwo-lesnictwo/uprawy-rolne-i-ogrodnicze/'),
  ('commodities', 2, 'Organized commodity exchanges operate standardized grading systems to ensure every unit delivered meets verifiable physical criteria.', 'Warenbörsen definieren verbindliche Qualitätsstandards, damit gehandelte Einheiten stets verifizierbare Anforderungen erfüllen.', 'Giełdy towarowe i izby rozliczeniowe definiują ścisłe standardy jakościowe, gwarantujące jednolitość parametrów dostarczanego surowca.', 'https://www.irgit.pl/'),
  ('commodities', 3, 'Commodity clearinghouses act as central counterparties, mitigating settlement risk for both raw material producers and industrial consumers.', 'Zentrale Clearinghäuser treten als Kontrahent zwischen Käufer und Verkäufer und sichern Erzeuger wie Abnehmer gegen Ausfallrisiken ab.', 'Izba Rozliczeniowa Giełd Towarowych (IRGiT) pełni rolę centralnego kontrahenta, eliminując ryzyko niewypłacalności stron transakcji.', 'https://www.knf.gov.pl/podmioty/Podmioty_rynku_kapitalowego/izby_rozliczeniowe'),
  ('commodities', 4, 'National energy and market regulators oversee commodity trading to prevent fraudulent market manipulation and ensure fair transparency.', 'Regulierungsbehörden wie die Bundesnetzagentur und BaFin überwachen Rohstoffmärkte zur Verhinderung von Marktmanipulation.', 'Urząd Regulacji Energetyki (URE) oraz KNF nadzorują handel surowcami energetycznymi w celu zapobiegania manipulacjom rynkowym.', 'https://www.ure.gov.pl/'),
  ('gold', 0, 'Central banks hold substantial gold reserves as a strategic anchor of national financial stability and sovereign creditworthiness.', 'Die Deutsche Bundesbank hält mit über 3.300 Tonnen eine der weltweit größten Goldreserven zur Sicherung nationaler Stabilität.', 'Narodowy Bank Polski (NBP) systematycznie powiększa rezerwy złota (przekraczające 400 ton), budując strategiczną poduszkę bezpieczeństwa kraju.', 'https://nbp.pl/rezerwy-dewizowe-i-zloto/'),
  ('gold', 1, 'Central banking authorities maintain strict security protocols, physical vault audits, and independent inventory assays for bullion assets.', 'Die Bundesbank führt regelmäßige Stichproben, Barrenprüfungen und Inventuren ihrer Goldbestände durch.', 'NBP przeprowadza rygorystyczne audyty, kontrole wagi i próby czystości sztab złota przechowywanych w skarbcach krajowych i zagranicznych.', 'https://nbp.pl/publikacje/raport-roczny/'),
  ('gold', 2, 'Historical monetary institutions show that gold functioned as universal money across centuries because it is scarce, durable, and chemically inert.', 'Geldmuseen der Notenbanken dokumentieren die historische Rolle von Gold als universelles Wertaufbewahrungsmittel.', 'Centrum Pieniądza NBP im. Sławomira S. Skrzypka prezentuje historyczną ewolucję kruszców i rolę złota jako niezmiennego miernika wartości.', 'https://www.cpnbp.pl/'),
  ('gold', 3, 'Global central banking studies classify gold as a premier safe-haven asset with negligible default risk during systemic financial crises.', 'Europäische Notenbanken stufen Gold als Reserveaktivum ohne Gegenparteirisiko in Krisenzeiten ein.', 'Europejski Bank Centralny i NBP klasyfikują złoto jako aktywum rezerwowe wolne od ryzyka kredytowego emitenta (brak ryzyka niewypłacalności).', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/what_is_money.en.html'),
  ('gold', 4, 'Financial supervisory authorities advise savers that physical gold does not generate cash flow or interest, functioning primarily as a hedge.', 'Verbraucherzentralen und Aufsichtsbehörden weisen darauf hin, dass Gold keine Zinsen abwirft, sondern der Risikoabsicherung dient.', 'Komisja Nadzoru Finansowego (KNF) przypomina, że złoto lokacyjne nie przynosi odsetek ani dywidend, lecz służy dywersyfikacji i ochronie kapitału.', 'https://www.knf.gov.pl/dla_konsumenta/ostrzezenia_publiczne'),
  ('stocks', 0, 'Corporate law defines joint-stock corporations as capital companies whose equity is divided into transferable shares.', 'Das Aktiengesetz (§ 1) definiert die AG als Gesellschaft mit eigener Rechtspersönlichkeit, deren Grundkapital in Aktien zerlegt ist.', 'Kodeks spółek handlowych (art. 301 KSH) stanowi, że kapitał zakładowy spółki akcyjnej dzieli się na akcje o równej wartości nominalnej.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20000941037'),
  ('stocks', 1, 'Corporate statutes establish that shareholders are entitled to a share in company balance sheet profits through dividend distributions.', 'Aktionäre haben nach AktG § 60 Anspruch auf den Bilanzgewinn, sofern die Hauptversammlung die Ausschüttung beschließt.', 'Akcjonariusz ma ustawowe prawo do udziału w zysku wykazanym w sprawozdaniu finansowym (dywidenda) zgodnie z art. 347 KSH.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20000941037'),
  ('stocks', 2, 'Regulated stock exchanges maintain fair, transparent, and orderly secondary markets for equity securities.', 'Die Frankfurter Wertpapierbörse und Xetra bieten geregelte Handelsplätze mit transparenter Preisbildung.', 'Giełda Papierów Wartościowych w Warszawie (GPW) prowadzi regulowany rynek giełdowy zapewniający przejrzystość obrotu i ochronę inwestorów.', 'https://www.gpw.pl/o-nas'),
  ('stocks', 3, 'Financial market authorities supervise securities markets to prevent market abuse and ensure investor information disclosure.', 'Die Bundesanstalt für Finanzdienstleistungsaufsicht (BaFin) überwacht den Wertpapierhandel und Insiderverbote.', 'Komisja Nadzoru Finansowego (KNF) sprawuje nadzór nad rynkiem kapitałowym i egzekwuje obowiązki informacyjne spółek publicznych.', 'https://www.knf.gov.pl/dla_rynku/rynek_kapitalowy'),
  ('stocks', 4, 'Benchmark equity indices track the performance of leading blue-chip corporations representing the broader national economy.', 'Der Leitindex DAX bildet die Wertentwicklung der 40 größten und liquidesten deutschen Unternehmen ab.', 'Indeks WIG20 odzwierciedla koniunkturę giełdową, grupując 20 największych i najbardziej płynnych spółek z warszawskiego parkietu.', 'https://www.gpwbenchmark.pl/'),
  ('stocks', 5, 'Investor education guidelines highlight that equity investments represent real productive capacity but carry business and price volatility risks.', 'Verbraucherzentralen betonen, dass Aktien Chancen auf Produktivitätswachstum bieten, aber Kursschwankungen unterliegen.', 'KNF i instytucje edukacji finansowej przypominają, że akcje dają udział w realnym wzroście gospodarczym, lecz wiążą się z ryzykiem utraty części kapitału.', 'https://www.knf.gov.pl/dla_konsumenta/edukacja_finansowa'),
  ('bonds', 0, 'Public finance acts authorize sovereign states to issue treasury bonds to fund public investments and state budget deficits.', 'Bundesanleihen werden von der Bundesrepublik Deutschland begeben, um staatliche Ausgaben und Investitionen zu decken.', 'Ustawa o finansach publicznych upoważnia Ministra Finansów do emisji skarbowych papierów wartościowych na pokrycie potrzeb pożyczkowych budżetu państwa.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20091571240'),
  ('bonds', 1, 'Bond statutes establish that a bond represents a formal acknowledgment of debt where the issuer commits to pay coupons and repay the principal.', 'Das BGB (§ 793) regelt Inhaberschuldverschreibungen als Verpflichtung zur Leistung an den jeweiligen Inhaber der Urkunde.', 'Ustawa o obligacjach (art. 4) definiuje obligację jako papier wartościowy emitowany w serii, w którym emitent stwierdza, że jest dłużnikiem właściciela obligacji.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20150000238'),
  ('bonds', 2, 'Secondary bond exchange platforms allow market trading of fixed-income instruments between institutional and individual investors.', 'Die Börse Frankfurt und Handelsplätze für Rentenpapiere ermöglichen den vorzeitigen Verkauf von Anleihen zum Marktkurs.', 'Rynek Catalyst prowadzony przez Giełdę Papierów Wartościowych w Warszawie (GPW) umożliwia obrót obligacjami skarbowymi, komunalnymi i korporacyjnymi.', 'https://gpwcatalyst.pl/o-rynku'),
  ('bonds', 3, 'Financial economics documents the inverse relationship between market interest rates and secondary market bond prices (bond duration).', 'Wirtschaftslexika und Aufsichten erklären, dass Anleihekurse bei steigenden Marktzinsen fallen und umgekehrt (Zinsänderungsrisiko).', 'KNF i literatura finansowa wyjaśniają zjawisko ryzyka stopy procentowej: gdy rynkowe stopy procentowe rosną, rynkowa cena wyemitowanych wcześniej obligacji o stałym kuponie spada.', 'https://www.knf.gov.pl/dla_konsumenta/edukacja_finansowa'),
  ('bonds', 4, 'National debt management agencies offer dedicated retail bond programs providing household savings protected by sovereign credit guarantees.', 'Die Deutsche Finanzagentur informiert Bürger über die Merkmale und Renditen von Bundeswertpapieren.', 'Serwis Obligacji Skarbowych Ministerstwa Finansów umożliwia obywatelom zakup obligacji detalicznych z pełną gwarancją wypłaty kapitału przez Skarb Państwa.', 'https://www.obligacjeskarbowe.pl/'),
  ('stocksvsbonds', 0, 'Insolvency statutes establish a strict statutory waterfall where secured and unsecured creditors are satisfied before equity shareholders receive residual funds.', 'Die Insolvenzordnung (InsO § 38) regelt den gesetzlichen Gläubigervorrang gegenüber nachrangigen Anteilseignern.', 'Prawo upadłościowe (art. 342) ustala kolejność podziału funduszów masy upadłości: wierzytelności podlegają zaspokojeniu w ściśle określonych kategoriach przed wspólnikami i akcjonariuszami.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20030600535'),
  ('stocksvsbonds', 1, 'Commercial codes define equity shares as residual capital bearing primary business risks and uncapped upside potential.', 'Aktien verbriefen Eigenkapital mit voller Teilhabe am Gewinn, tragen jedoch das unternehmerische Verlustrisiko.', 'Kodeks spółek handlowych reguluje kapitał akcyjny jako wkład właścicielski, uprawniający do dywidendy, lecz ponoszący ryzyko strat przedsiębiorstwa.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20000941037'),
  ('stocksvsbonds', 2, 'Corporate debt instruments legally obligate the issuing entity to service periodic coupons and repay par value regardless of profitability.', 'Anleihen stellen schuldrechtliche Zahlungsversprechen dar, die unabhängig vom Jahresergebnis bedient werden müssen.', 'Ustawa o obligacjach stanowi, że emitent odpowiada całym swoim majątkiem za terminową wypłatę świadczeń pieniężnych (kuponów i wykupu).', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20150000238'),
  ('stocksvsbonds', 3, 'Modern portfolio theory demonstrates that combining non-correlated equities and fixed-income assets optimizes long-term risk-adjusted returns.', 'Verbraucherzentralen und Ökonomen empfehlen eine Diversifikation über breit gestreute Aktien-ETFs und solide Rentenwerte.', 'Komisja Nadzoru Finansowego zaleca dywersyfikację portfela inwestycyjnego między instrumenty udziałowe (akcje) a dłużne (obligacje), by ograniczyć ryzyko wahań.', 'https://www.knf.gov.pl/dla_konsumenta/edukacja_finansowa'),
  ('stocksvsbonds', 4, 'Securities and exchange authorities classify corporate bonds and sovereign debt as fixed-income securities subject to credit rating appraisals.', 'Aufsichtsbehörden fordern transparente Risikoklassifizierungen und Bonitätsbewertungen (Ratings) für Anleihen.', 'KNF nadzoruje ratingi kredytowe i wymogi informacyjne dla papierów dłużnych notowanych na rynkach regulowanych.', 'https://www.knf.gov.pl/dla_rynku/rynek_kapitalowy'),
  ('derivatives', 0, 'Securities trading acts legally define financial derivatives as contracts whose price depends directly on an underlying asset, rate, or index.', 'Das Wertpapierhandelsgesetz (WpHG § 2) definiert Derivate als Finanzinstrumente, deren Wert sich von Basiswerten ableitet.', 'Ustawa o obrocie instrumentami finansowymi (art. 2) klasyfikuje jako instrumenty pochodne kontrakty opcyjne, terminowe (futures/forward), swapy i inne prawa majątkowe zależne od instrumentów bazowych.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20051831538'),
  ('derivatives', 1, 'Economic principles distinguish price hedging from speculation, recognizing hedging as risk management designed to reduce commercial exposure.', 'Ökonomische Lehrwerke definieren Hedging als Risikomanagement zur neutralisierenden Absicherung gegen ungünstige Marktbewegungen.', 'KNF i literatura bankowa definiują hedging jako transakcję zabezpieczającą, której celem jest ograniczenie ryzyka strat wynikających ze zmian cen rynkowych, kursów walut lub stóp procentowych.', 'https://www.knf.gov.pl/dla_konsumenta/edukacja_finansowa'),
  ('derivatives', 2, 'Regulated commodity exchange acts establish transparent clearing and delivery mechanisms for physical agricultural and energy goods.', 'Die EEX und Terminbörsen bieten regulierte Handelsplätze mit zentralem Kontrahenten (Clearinghouse) für Energie und Rohstoffe.', 'Ustawa o giełdach towarowych reguluje obrót towarami giełdowymi (w tym energią, prawami majątkowymi i produktami rolnymi) na licencjonowanych rynkach prowadzonych przez TGE.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20001031099'),
  ('derivatives', 3, 'International airline and shipping trade organizations document that major commercial carriers routinely hedge jet fuel to ensure operational stability.', 'Luftfahrtverbände und Geschäftsberichte belegen, dass Airlines Treibstoffkosten über Terminverträge absichern.', 'Raporty branżowe IATA oraz sprawozdania przewoźników lotniczych potwierdzają powszechne stosowanie instrumentów pochodnych na paliwo lotnicze dla stabilizacji kosztów operacyjnych.', 'https://www.iata.org/en/publications/economics/'),
  ('derivatives', 4, 'Financial supervisory authorities enforce margin requirements and reporting obligations under derivatives market regulations (EMIR) to prevent systemic defaults.', 'Die Europäische Marktinfrastrukturverordnung (EMIR) und BaFin überwachen Risikominderungsverfahren für OTC-Derivate.', 'Rozporządzenie EMIR oraz KNF nakładają na uczestników rynku wymogi zabezpieczeń depozytowych (margins) i raportowania transakcji pochodnych w celu ochrony stabilności finansowej.', 'https://www.knf.gov.pl/dla_rynku/rynek_kapitalowy/rozporzadzenie_emir'),
  ('philanthropy', 0, 'Public charity and trust registries record tens of thousands of active non-profit foundations dedicated to social, scientific, and educational purposes.', 'Der Bundesverband Deutscher Stiftungen verzeichnet über 25.000 rechtsfähige Stiftungen des bürgerlichen Rechts in Deutschland.', 'Ustawa o fundacjach (Dz.U. z 1984 r. Nr 21 poz. 97) reguluje powoływanie fundacji do realizacji celów zgodnych z podstawowymi interesami Rzeczypospolitej Polskiej, w szczególności ochrony zdrowia, oświaty i nauki.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19840210097'),
  ('philanthropy', 1, 'Public benefit laws grant qualified non-profit organizations public benefit status, allowing citizens to donate a direct percentage of income tax to certified charities.', 'Das Gemeinnützigkeitsrecht im Steuerrecht (Abgabenordnung §§ 51 ff.) gewährt steuerbegünstigten Körperschaften rechtliche und steuerliche Privilegien.', 'Ustawa o działalności pożytku publicznego i o wolontariacie reguluje status Organizacji Pożytku Publicznego (OPP) oraz uprawnienie podatników do przekazania 1,5% podatku dochodowego od osób fizycznych.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20030960873'),
  ('philanthropy', 2, 'Civil legal frameworks govern the incorporation and asset segregation of autonomous perpetual legal entities.', 'Das Bürgerliche Gesetzbuch (BGB § 80) regelt die Entstehung einer rechtsfähigen Stiftung durch Stiftungsgeschäft und Genehmigung.', 'Zgodnie z przepisami prawa cywilnego fundacja uzyskuje osobowość prawną z chwilą wpisu do Krajowego Rejestru Sądowego (KRS), a jej majątek staje się odrębny od majątku fundatora.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19971210769'),
  ('philanthropy', 3, 'Statutory foundation charters mandate that foundation assets be permanently managed to fulfill the founder''s designated non-profit charter.', 'BGB § 83 schreibt vor, dass das Stiftungsvermögen der dauernden Erfüllung des vom Stifter bestimmten Zwecks zu widmen ist.', 'Statut fundacji określa jej cele, majątek i zasady gospodarowania dochodami, zobowiązując zarząd do przeznaczania wypracowanych zysków wyłącznie na cele statutowe.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19840210097'),
  ('philanthropy', 4, 'Institutional endowment governance mandates real preservation of capital principal while disbursing only sustainable dividend and interest yields.', 'Der Grundsatz der Vermögenserhaltung verpflichtet Stiftungen, ihr Stiftungskapital real zu sichern und nur Erträge auszuschütten.', 'Zasada ochrony kapitału żelaznego (endowmentu) polega na trwałym zachowaniu realnej wartości kapitału i finansowaniu działalności pożytku publicznego jedynie z odsetek i dywidend.', 'https://www.pozytek.gov.pl'),
  ('whygovernment', 0, 'Constitutional local self-government articles assign fundamental public welfare tasks and infrastructure coordination to democratically elected municipal councils.', 'Die Gemeindeordnungen der Bundesländer weisen Städten und Gemeinden das Recht der kommunalen Selbstverwaltung für alle örtlichen Angelegenheiten zu.', 'Konstytucja Rzeczypospolitej Polskiej (art. 16) stanowi, że ogół mieszkańców jednostek zasadniczego podziału terytorialnego stanowi z mocy prawa wspólnotę samorządową, która uczestniczy w sprawowaniu władzy publicznej.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('whygovernment', 1, 'Municipal statutes obligate local authorities to maintain public utilities, primary education, local road networks, and public health infrastructure.', 'Gemeinden sind zur Erfüllung von Pflichtaufgaben wie Trinkwasserversorgung, Abwasserbeseitigung, Brandschutz und Schulbau gesetzlich verpflichtet.', 'Ustawa o samorządzie gminnym (art. 7) nakłada na gminę obowiązek zaspokajania zbiorowych potrzeb wspólnoty, w tym ładu przestrzennego, dróg, wodociągów, kanalizacji, ochrony zdrowia i edukacji publicznej.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19900160095'),
  ('whygovernment', 2, 'Economic public finance theory identifies public goods by non-excludability and non-rivalry, showing that free markets underprovide them without collective funding.', 'Finanzwissenschaftliche Grundlagen definieren öffentliche Güter über Nicht-Ausschließbarkeit und Nicht-Rivalität im Konsum.', 'Teoria finansów publicznych definiuje dobra publiczne jako dobra charakteryzujące się brakiem rywalizacji w konsumpcji i niemożnością wykluczenia z użytkowania, wymagające finansowania ze środków publicznych.', 'https://stat.gov.pl'),
  ('whygovernment', 3, 'State and federal public finance laws empower local authorities to collect municipal taxes and user fees to fund local infrastructure maintenance.', 'Das Grundgesetz (Art. 106 Abs. 6) garantiert den Gemeinden das Aufkommen der Realsteuern (Gewerbe- und Grundsteuer) zur Finanzierung ihrer Aufgaben.', 'Ustawa o dochodach jednostek samorządu terytorialnego reguluje źródła finansowania gmin, w tym udziały w podatkach dochodowych (PIT i CIT) oraz podatki i opłaty lokalne.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20032031966'),
  ('whygovernment', 4, 'Democratic constitutions declare that all public power originates from the sovereign people and is exercised directly or through elected representatives.', 'Artikel 20 des Grundgesetzes bestimmt: ''Alle Staatsgewalt geht vom Volke aus. Sie wird vom Volke in Wahlen und Abstimmungen ausgeübt.''', 'Art. 4 Konstytucji RP deklaruje, że władza zwierzchnia w Rzeczypospolitej Polskiej należy do Narodu, który sprawuje ją przez swoich przedstawicieli lub bezpośrednio.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('elections', 0, 'Constitutional election provisions guarantee that parliamentary deputies are chosen in general, direct, free, equal, and secret elections.', 'Artikel 38 des Grundgesetzes garantiert, dass die Abgeordneten des Deutschen Bundestages in allgemeiner, unmittelbarer, freier, gleicher und geheimer Wahl gewählt werden.', 'Art. 96 Konstytucji Rzeczypospolitej Polskiej stanowi, że wybory do Sejmu są powszechne, równe, bezpośrednie i proporcjonalne oraz odbywają się w głosowaniu tajnym.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('elections', 1, 'Independent election management bodies supervise electoral rolls, polling places, balloting neutrality, and tally integrity.', 'Die Bundeswahlleiterin überwacht die ordnungsgemäße Durchführung der Bundestagswahl und verkündet das amtliche Endergebnis.', 'Kodeks wyborczy powierza stałe sprawowanie nadzoru nad przestrzeganiem prawa wyborczego Państwowej Komisji Wyborczej (PKW) oraz Krajowemu Biuru Wyborczemu.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20110210112'),
  ('elections', 2, 'Constitutional law specifies fixed parliamentary terms ensuring periodic elections and institutional accountability to the electorate.', 'Der Deutsche Bundestag wird auf vier Jahre gewählt; vorzeitige Neuwahlen sind an strenge verfassungsrechtliche Hürden geknüpft.', 'Art. 98 Konstytucji RP ustala czteroletnią kadencję Sejmu i Senatu, gwarantując regularność weryfikacji władzy przez obywateli.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('elections', 3, 'Statutory electoral codes define mandatory voter secrecy safeguards including private voting booths and uniform locked ballot receptacles.', 'Das Bundeswahlgesetz regelt detailliert die Bereitstellung von blickdichten Wahlkabinen und versiegelten Wahlurnen in allen Wahllokalen.', 'Kodeks wyborczy nakazuje zapewnienie w każdym lokalu wyborczym osłoniętych miejsc zapewniających tajność głosowania oraz przezroczystych, zapieczętowanych urn.', 'https://pkw.gov.pl'),
  ('elections', 4, 'Political science consensus highlights competitive universal elections as the core peaceful mechanism for political accountability and power transition.', 'Die Bundeszentrale für politische Bildung betont Wahlen als zentrales Instrument demokratischer Herrschaftskontrolle und friedlichen Regierungswechsels.', 'Opracowania politologiczne i edukacja obywatelska wskazują wolne wybory jako fundament pokojowej sukcesji władzy oraz odpowiedzialności politycznej przed suwerenem.', 'https://www.batory.org.pl'),
  ('democracy', 0, 'Constitutional democracy provisions define the state as a democratic state under the rule of law realizing social justice principles.', 'Artikel 20 Absatz 1 des Grundgesetzes bestimmt die Bundesrepublik Deutschland als demokratischen und sozialen Bundesstaat.', 'Art. 2 Konstytucji Rzeczypospolitej Polskiej stanowi: ''Rzeczpospolita Polska jest demokratycznym państwem prawnym, urzeczywistniającym zasady sprawiedliwości społecznej''.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('democracy', 1, 'Constitutional equality clauses mandate that all persons are equal before the law and have equal rights in public life.', 'Artikel 3 Absatz 1 des Grundgesetzes garantiert: ''Alle Menschen sind vor dem Gesetz gleich.''', 'Art. 32 Konstytucji RP gwarantuje: ''Wszyscy są wobec prawa równi. Wszyscy mają prawo do równego traktowania przez władze publiczne''.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('democracy', 2, 'Constitutional courts protect fundamental civil liberties, minority interests, and institutional balance against executive or legislative overreach.', 'Das Bundesverfassungsgericht wacht als oberster Hüter des Grundgesetzes über die Einhaltung der Grundrechte und Verfassungsgrenzen.', 'Trybunał Konstytucyjny orzeka w sprawach zgodności ustaw i umów międzynarodowych z Konstytucją RP, chroniąc nienaruszalność praw obywatelskich.', 'https://trybunal.gov.pl'),
  ('democracy', 3, 'Democratic political culture frameworks highlight parliamentary deliberation, coalition building, and consensus negotiation as foundational governance norms.', 'Die Bundeszentrale für politische Bildung definiert Kompromissfähigkeit und Dialogbereitschaft als unverzichtbare Tugenden lebendiger Demokratie.', 'Kultura polityczna demokracji opiera się na dialogu społecznym, wolności debaty, prawach opozycji oraz poszukiwaniu kompromisu służącego dobru wspólnemu.', 'https://www.sejm.gov.pl/Sejm10.nsf/page.xsp/historia'),
  ('democracy', 4, 'Separation of powers doctrines distribute sovereignty across legislative, executive, and judicial branches to avert autocratic concentrations of power.', 'Gewaltenteilung nach Art. 20 Abs. 2 GG trennt Gesetzgebung, vollziehende Gewalt und Rechtsprechung zur gegenseitigen Hemmung und Kontrolle.', 'Art. 10 Konstytucji RP ustala ustrój oparty na podziale i równowadze władzy ustawodawczej, wykonawczej i sądowniczej.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('monarchy', 0, 'Constitutional history marks the transition from hereditary dynastic rule to parliamentary republics across Europe and Asia after major 20th-century geopolitical transformations.', 'Das Deutsche Kaiserreich endete im November 1918 mit der Abdankung Wilhelms II. und der Ausrufung der Weimarer Republik.', 'Konstytucja marcowa z 1921 r. definitywnie potwierdziła republikański ustrój odrodzonej Polski, znosząc wszelkie przywileje rodowe i tytuły szlacheckie.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19210440267'),
  ('monarchy', 1, 'Republican constitutional law vests sovereignty exclusively in the nation, exercising power through elected representatives or direct referenda.', 'Die Weimarer Reichsverfassung von 1919 begründete die parlamentarische Demokratie in Deutschland.', 'Art. 4 Konstytucji RP stanowi, że władza zwierzchnia w Rzeczypospolitej Polskiej należy do Narodu, sprawującego ją przez swoich przedstawicieli lub bezpośrednio.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('monarchy', 2, 'Contemporary constitutional monarchies in Europe maintain strict separation between ceremonial heads of state and democratically elected parliaments.', 'Mehrere europäische Demokratien wie das Vereinigte Königreich, Schweden, Dänemark und die Niederlande funktionieren als konstitutionelle Monarchien.', 'Współczesne europejskie monarchie konstytucyjne (m.in. Wielka Brytania, Szwecja, Norwegia, Hiszpania) ograniczają rolę monarchy do funkcji reprezentacyjnych, oddając władzę parlamentom.', 'https://www.parliament.uk/about/how/role/monarchy/'),
  ('monarchy', 3, 'Historical political science studies demonstrate high governance volatility in absolute systems where succession depends on biological inheritance rather than merit.', 'Historische Analysen zeigen die Anfälligkeit absoluter Erbmonarchien bei ungeeigneten Thronfolgern ohne parlamentarische Kontrollorgane.', 'Badania politologiczne i historyczne wskazują na wysokie ryzyko kryzysów państwowych w monarchiach absolutnych, w których sukcesja zależy od biologicznego przypadku, a nie kompetencji.', 'https://www.dhm.de/lemo/kapitel/kaiserreich.html'),
  ('monarchy', 4, 'Comparative institutional archives trace how modern parliamentary supremacy established ministerial responsibility to elected legislative bodies.', 'Das Archiv des Deutschen Bundestages dokumentiert den langen Weg vom monarchischen Obrigkeitsstaat zur parlamentarischen Volkssouveränität.', 'Zbiory Biblioteki Sejmowej i Archiwum Akt Nowych dokumentują ewolucję od rządów monarchicznych do pełnej suwerenności narodu i odpowiedzialności rządu przed Sejmem.', 'https://biblioteka.sejm.gov.pl'),
  ('dictatorship', 0, 'Constitutional anti-authoritarian clauses prohibit political organizations whose programs appeal to totalitarian methods and practices of Nazism, fascism, or communism.', 'Artikel 79 Absatz 3 des Grundgesetzes (die Ewigkeitsklausel) verbietet jede Änderung der Menschenwürde sowie der demokratischen Grundordnung.', 'Art. 13 Konstytucji RP zakazuje istnienia partii i organizacji odwołujących się w swoich programach do totalitarnych metod i praktyk nazizmu, faszyzmu i komunizmu.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('dictatorship', 1, 'Constitutional human dignity clauses establish inherent and inalienable dignity as the untouchable foundation of all state and individual rights.', 'Artikel 1 Absatz 1 des Grundgesetzes bestimmt: ''Die Würde des Menschen ist unantastbar. Sie zu achten und zu schützen ist Verpflichtung aller staatlichen Gewalt.''', 'Art. 30 Konstytucji RP deklaruje: ''Przyrodzona i niezbywalna godność człowieka stanowi źródło wolności i praw człowieka i obywatela. Jest ona nienaruszalna, a jej poszanowanie i ochrona jest obowiązkiem władz publicznych''.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('dictatorship', 2, 'Constitutional free speech provisions guarantee freedom of expression and explicitly prohibit preemptive censorship of news media.', 'Artikel 5 des Grundgesetzes garantiert die Pressefreiheit und bestimmt ausdrücklich: ''Eine Zensur findet nicht statt.''', 'Art. 54 Konstytucji RP gwarantuje wolność wyrażania swoich poglądów oraz pozyskiwania i rozpowszechniania informacji, jednoznacznie zakazując cenzury prewencyjnej.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('dictatorship', 3, 'Historical archives document that authoritarian suppression of feedback mechanisms and independent journalism causes systemic blindness and governance failures.', 'Historische Studien des Deutschen Historischen Museums belegen den Zusammenbruch staatlicher Fehlerrückmeldung unter totalitärer Pressekontrolle.', 'Zbiory Europejskiego Centrum Solidarności i Ośrodka KARTA dokumentują, jak monopol informacyjny i brak niezależnej prasy w PRL prowadziły do zatajania katastrof i kryzysów.', 'https://ecs.gda.pl'),
  ('dictatorship', 4, 'Civic education institutions define dictatorship by the lack of separation of powers, absence of legitimate political opposition, and violation of human rights.', 'Materialien der Bundeszentrale für politische Bildung definieren Diktaturen durch das Fehlen von Gewaltenteilung und die Unterdrückung der Opposition.', 'Opracowania edukacyjne Centrum Edukacji Obywatelskiej definiują dyktaturę poprzez brak trójpodziału władzy, eliminację opozycji i tłumienie praw obywatelskich.', 'https://ceo.org.pl'),
  ('capitalism', 0, 'Constitutional economic provisions establish the social market economy based on freedom of economic activity, private property, and solidarity as the bedrock of the national economic system.', 'Das Konzept der Sozialen Marktwirtschaft wurde im Nachkriegsdeutschland von Ludwig Erhard und Alfred Müller-Armack begründet.', 'Art. 20 Konstytucji Rzeczypospolitej Polskiej stanowi: ''Społeczna gospodarka rynkowa oparta na wolności działalności gospodarczej, własności prywatnej oraz solidarności, dialogu i współpracy partnerów społecznych stanowi podstawę ustroju gospodarczego Rzeczypospolitej Polskiej''.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('capitalism', 1, 'Constitutional property clauses protect the right to property, inheritance, and business freedom while subjecting ownership to statutory public interest obligations.', 'Artikel 14 des Grundgesetzes schützt das Privateigentum, bestimmt aber zugleich: ''Eigentum verpflichtet. Sein Gebrauch soll zugleich dem Wohle der Allgemeinheit dienen.''', 'Art. 21 i art. 64 Konstytucji RP chronią własność i prawo dziedziczenia, zastrzegając, że własność może być ograniczona tylko w drodze ustawy i tylko w zakresie, w jakim nie narusza jej istoty.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('capitalism', 2, 'Independent antimonopoly regulators monitor mergers, penalize cartels, and sanction abuses of dominant market position to preserve consumer price discovery.', 'Das Bundeskartellamt bekämpft Monopolbildungen und Kartellabsprachen zum Schutz von Konsumenten und fairem Wettbewerb.', 'Urząd Ochrony Konkurencji i Konsumentów (UOKiK) przeciwdziała praktykom monopolistycznym, niedozwolonym porozumieniom cenowym oraz chroni zbiorowe interesy konsumentów.', 'https://uokik.gov.pl'),
  ('capitalism', 3, 'National statistical offices record that millions of registered private micro, small, and medium enterprises generate the majority of employment and gross domestic product.', 'Statistische Daten von Destatis belegen, dass mittelständische Privatunternehmen das Rückgrat der deutschen Wirtschaftsleistung und Beschäftigung bilden.', 'Główny Urząd Statystyczny (GUS) oraz PARP raportują, że sektor prywatnych małych i średnich przedsiębiorstw tworzy blisko połowę polskiego PKB i zatrudnia większość pracujących.', 'https://stat.gov.pl'),
  ('capitalism', 4, 'Economic history documents that replacing state production quotas with decentralized price mechanisms dramatically increases innovation, resource efficiency, and consumer welfare.', 'Das Bundesministerium für Wirtschaft und Klimaschutz dokumentiert die ordoliberale Marktkoordination als Grundlage für Wohlstand für alle.', 'Doświadczenie transformacji gospodarczej w Polsce po 1989 r. potwierdza, że uwolnienie przedsiębiorczości i cen wyeliminowało kolejki i stworzyło nowoczesną, dynamiczną gospodarkę.', 'https://www.gov.pl/web/rozwoj-technologia'),
  ('communism', 0, 'Economic historians analyze post-war command economies, such as the Polish People''s Republic (PRL) and East Germany (GDR), which operated through multi-year central production plans and state monopolies.', 'Die Deutsche Demokratische Republik (DDR) betrieb eine staatlich gelenkte Planwirtschaft mit Fünfjahresplänen und der Staatlichen Plankommission.', 'W Polskiej Rzeczypospolitej Ludowej (PRL) gospodarką kierowała Państwowa Komisja Planowania Gospodarczego (PKPG), która ustalała odgórne plany wieloletnie, limity produkcyjne i urzędowe ceny.', 'https://ipn.gov.pl'),
  ('communism', 1, 'Archival records document chronic shortages of consumer goods, pervasive queues, and formal rationing card systems across socialist economies.', 'Historische Quellen dokumentieren anhaltenden Mangel an Konsumgütern, lange Wartezeiten und technologische Stagnation in der DDR.', 'Archiwa Instytutu Pamięci Narodowej (IPN) dokumentują chroniczny niedobór towarów w PRL, wielogodzinne kolejki komitetowe oraz system kartek żywnościowych (reglamentację).', 'https://ipn.gov.pl'),
  ('communism', 2, 'Nobel laureate Friedrich Hayek identified the ''local knowledge problem'', explaining that vital economic information is dispersed among millions of individuals and cannot be aggregated by a central bureaucracy.', 'Ökonomen wie Friedrich Hayek analysierten das ''lokale Wissensproblem'' als unüberwindbare Grenze zentraler Wirtschaftsplanung.', 'Laureat Nagrody Nobla Friedrich Hayek sformułował pojęcie ''problemu wiedzy'', dowodząc, że wiedza o potrzebach i zasobach jest rozproszona wśród milionów ludzi i żadne centralne biuro nie zdoła jej zgromadzić.', 'https://www.nobelprize.org/prizes/economic-sciences/1974/hayek/facts/'),
  ('communism', 3, 'Hungarian economist János Kornai coined the term ''shortage economy'' to describe systemic supply failures inherent in soft-budget state-owned enterprises.', 'János Kornai prägte den Begriff der ''Mangelwirtschaft'' zur theoretischen Erklärung der Versorgungsengpässe in sozialistischen Staaten.', 'Węgierski ekonomista János Kornai opisał to zjawisko jako ''gospodarkę niedoboru'', wynikającą z braku dyscypliny finansowej w państwowych przedsiębiorstwach.', 'https://global.oup.com'),
  ('communism', 4, 'The historic transition of 1989/1990 restored private property rights, abolished central price controls, and sparked rapid consumer market revitalization in Central Europe.', 'Mit der Wiedervereinigung 1990 und der Währungsunion übernahm Ostdeutschland die Soziale Marktwirtschaft der Bundesrepublik.', 'Uchwalenie Ustawy o działalności gospodarczej z 1988 r. (tzw. ustawa Wilczka) oraz reformy 1989/1990 przywróciły wolność gospodarczą, znosząc monopol państwa i likwidując kolejki.', 'https://isap.sejm.gov.pl'),
  ('powertriangle', 0, 'Constitutional separation of powers mandates institutional checks and balances among legislative, executive, and independent judicial branches.', 'Artikel 20, Absatz 2 des Grundgesetzes verankert die Gewaltenteilung in Gesetzgebung, vollziehende Gewalt und Rechtsprechung.', 'Art. 10 Konstytucji Rzeczypospolitej Polskiej stanowi: ''Ustrój Rzeczypospolitej Polskiej opiera się na podziale i równowadze władzy ustawodawczej, władzy wykonawczej i władzy sądowniczej''.', 'https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU19970780483'),
  ('powertriangle', 1, 'Constitutional courts and independent tribunals safeguard individual rights against executive overreach and ensure statutory compliance.', 'Das Bundesverfassungsgericht wacht als Hüter der Verfassung über die Einhaltung der Grundrechte und Grenzen staatlicher Macht.', 'Trybunał Konstytucyjny oraz niezawisłe sądy (art. 173 Konstytucji RP) stoją na straży praw obywatelskich i zgodności ustaw z konstytucją, chroniąc przed nadużyciami władzy.', 'https://trybunal.gov.pl'),
  ('powertriangle', 2, 'Tripartite social dialogue councils institutionalize negotiations between national trade unions, employer federations, and government ministries.', 'Die Tarifautonomie sichert den Sozialpartnern das Recht zu, Arbeitsbedingungen ohne staatlichen Eingriff eigenverantwortlich auszuhandeln.', 'Ustawa o Radzie Dialogu Społecznego z 2015 r. tworzy platformę trójstronnej współpracy pracowników, pracodawców i rządu w celu prowadzenia dialogu społecznego i zapewnienia pokoju społecznego.', 'https://rds.gov.pl'),
  ('powertriangle', 3, 'Supreme audit institutions provide independent parliamentary oversight, auditing state finances, budget execution, and public administration transparency.', 'Der Bundesrechnungshof prüft als unabhängiges Organ die gesamte Haushalts- und Wirtschaftsführung des Bundes.', 'Najwyższa Izba Kontroli (NIK), podległa Sejmowi, jest naczelnym organem kontroli państwowej badającym gospodarność i legalność wydatków publicznych.', 'https://www.nik.gov.pl'),
  ('powertriangle', 4, 'Political philosophy and Montesquieu''s doctrine of ''The Spirit of the Laws'' establish that liberty requires power checking power through autonomous counterweights.', 'Die Bundeszentrale für politische Bildung dokumentiert Gewaltenteilung als unverzichtbares Wesensmerkmal freiheitlicher Demokratien.', 'Doktryna Monteskiusza o podziale władz oraz tradycje demokratyczne dowodzą, że wolność obywateli jest bezpieczna tylko wtedy, gdy władza powstrzymuje władzę.', 'https://www.sejm.gov.pl'),
  ('mughals', 0, 'The Mughal Empire governed over one hundred million people across South Asia at its height in the seventeenth century.', 'Das Mogulreich regierte auf seinem Hoehepunkt im 17. Jahrhundert ueber hundert Millionen Menschen in Suedasien.', 'Imperium Mogołów u szczytu swojego rozwoju w XVII wieku obejmowało ponad sto milionów mieszkańców na subkontynencie indyjskim.', 'https://www.britannica.com/summary/Mughal-Dynasty'),
  ('mughals', 1, 'Emperor Akbar established the Ibadat Khana at Fatehpur Sikri in 1575 for philosophical and interfaith discussions.', 'Kaiser Akbar gruendete 1575 das Ibadat Khana in Fatehpur Sikri fuer philosophische und religioese Gespraeche.', 'Cesarz Akbar wzniósł w 1575 r. w Fatehpur Sikri Dom Mądrości (Ibadat Chana), gdzie mędrcy różnych tradycji prowadzili otwarte dysputy filozoficzne.', 'https://www.britannica.com/biography/Akbar'),
  ('mughals', 2, 'Mughal South Asia produced approximately twenty-four percent of global manufacturing output prior to European colonization.', 'Das Mogul-Reich erwirtschaftete vor der Kolonialisierung rund 24 Prozent der weltweiten Produktion.', 'Według badań historyków gospodarczych Indie w epoce Mogołów wytwarzały blisko 24 procent światowej produkcji manufakturowej, głównie tkanin bawełnianych.', 'https://www.cambridge.org/core/books/cambridge-economic-history-of-india/mughal-economy/1C3C62F5290D5EEF565158A55BBE0E78'),
  ('mughals', 3, 'The Grand Trunk Road was upgraded with regular caravan serais, mile markers, and security patrols connecting Bengal to Kabul.', 'Die Grand Trunk Road wurde mit Rasthaeusern, Meilensteinen und Wachposten von Bengalen bis Kabul ausgebaut.', 'Trakt Grand Trunk Road wyposażono w gęstą sieć karawanserajów, studni, słupów milowych i strażnic, łącząc Bengal z Kabulem.', 'https://whc.unesco.org/en/tentativelists/5492/'),
  ('mughals', 4, 'Mughal architecture synthesized Persian geometric domes with traditional Indian sandstone masonry and lotus carvings.', 'Die Mogul-Architektur verband persische Kuppelformen mit indischer Sandstein-Baukunst und Lotusmotiven.', 'Architektura Mogołów połączyła perskie motywy kopuł i łuków z indyjską tradycją rzeźby w piaskowcu i marmurze, czego szczytem stał się Tadź Mahal.', 'https://whc.unesco.org/en/list/252/'),
  ('mughals', 5, '1500s: Timbuktu is a city of books. Traders and students meet in a desert city.', '1500er: Timbuktu wird zur Stadt der Buecher. Haendler und Schueler treffen sich in einer Wuestenstadt.', 'XVI wiek: Timbuktu miastem ksiąg. Kupcy i uczniowie spotykają się w pustynnym mieście.', 'https://en.wikipedia.org/wiki/Timbuktu'),
  ('mughals', 6, '1517: Luther starts the Reformation. A German monk argues about church rules, and printed leaflets spread his ideas.', '1517: Luther loest die Reformation aus. Ein deutscher Moench streitet ueber Kirchenregeln, und gedruckte Flugblaetter verbreiten seine Ideen.', '1517: Luter rozpoczyna reformację. Niemiecki mnich spiera się o zasady Kościoła, a drukowane ulotki roznoszą jego pomysły.', 'https://en.wikipedia.org/wiki/Martin_Luther'),
  ('mughals', 7, '1521: The Aztec capital falls. Tenochtitlan, a city on a lake, is conquered by Spain and its allies.', '1521: Die Aztekenhauptstadt faellt. Tenochtitlan, eine Stadt im See, wird von Spanien und seinen Verbuendeten erobert.', '1521: Upada stolica Azteków. Tenochtitlan, miasto na jeziorze, zostaje podbite przez Hiszpanię i jej sojuszników.', 'https://en.wikipedia.org/wiki/Fall_of_Tenochtitlan'),
  ('mughals', 8, '1526: Babur founds the Mughal Empire. A new empire grows in northern India.', '1526: Babur gruendet das Mogulreich. Im Norden Indiens waechst ein neues Reich.', '1526: Babur zakłada imperium Mogołów. Na północy Indii rośnie nowe imperium.', 'https://en.wikipedia.org/wiki/Mughal_Empire'),
  ('mughals', 9, '1543: Copernicus puts the Sun in the middle. A Polish astronomer says Earth travels around the Sun.', '1543: Kopernikus stellt die Sonne in die Mitte. Ein polnischer Astronom sagt, die Erde kreist um die Sonne.', '1543: Kopernik stawia Słońce w centrum. Polski astronom twierdzi, że Ziemia krąży wokół Słońca.', 'https://en.wikipedia.org/wiki/Nicolaus_Copernicus'),
  ('mughals', 10, '1571: Manila galleons link Asia and the Americas. Ships carry Chinese silk across the Pacific for silver.', '1571: Manila-Galeonen verbinden Asien und Amerika. Schiffe bringen chinesische Seide ueber den Pazifik gegen Silber.', '1571: Galeony z Manili łączą Azję i Ameryki. Statki wożą chiński jedwab przez Pacyfik w zamian za srebro.', 'https://en.wikipedia.org/wiki/Manila_galleon'),
  ('mughals', 11, '1602: The Dutch East India Company starts. People can buy shares in a trading fleet.', '1602: Die Niederlaendische Ostindien-Kompanie entsteht. Menschen koennen Anteile an einer Handelsflotte kaufen.', '1602: Powstaje Holenderska Kompania Wschodnioindyjska. Ludzie mogą kupować udziały we flocie handlowej.', 'https://en.wikipedia.org/wiki/Dutch_East_India_Company'),
  ('mughals', 12, '1603: Tokugawa rule begins in Japan. Peace comes and cities like Edo grow big.', '1603: In Japan beginnt die Tokugawa-Zeit. Es herrscht Frieden und Staedte wie Edo werden gross.', '1603: W Japonii zaczynają się rządy Tokugawów. Nastaje pokój, a miasta takie jak Edo rosną.', 'https://en.wikipedia.org/wiki/Tokugawa_shogunate'),
  ('mughals', 13, '1609: Galileo turns a telescope to the sky. He sees moons circling Jupiter.', '1609: Galilei richtet ein Fernrohr zum Himmel. Er sieht Monde, die um den Jupiter kreisen.', '1609: Galileusz kieruje teleskop w niebo. Widzi księżyce krążące wokół Jowisza.', 'https://en.wikipedia.org/wiki/Galileo_Galilei'),
  ('mughals', 14, '1632: Shah Jahan begins the Taj Mahal. Thousands of builders make a white marble tomb.', '1632: Schah Jahan beginnt den Taj Mahal. Tausende Bauleute errichten ein Grabmal aus weissem Marmor.', '1632: Szahdżahan rozpoczyna budowę Tadż Mahal. Tysiące budowniczych wznosi grobowiec z białego marmuru.', 'https://en.wikipedia.org/wiki/Taj_Mahal'),
  ('mughals', 15, '1687: Newton explains gravity. The same pull makes an apple fall and the Moon circle Earth.', '1687: Newton erklaert die Schwerkraft. Dieselbe Kraft laesst einen Apfel fallen und den Mond die Erde umkreisen.', '1687: Newton wyjaśnia grawitację. Ta sama siła sprawia, że jabłko spada, a Księżyc krąży wokół Ziemi.', 'https://en.wikipedia.org/wiki/Isaac_Newton'),
  ('spicetrade', 0, 'The monsoon wind system reverses direction seasonally, enabling trans-oceanic navigation across the Indian Ocean since antiquity.', 'Das Monsun-Windsystem wechselt saisonal die Richtung und ermoeglichte seit der Antike Seefahrt ueber den Indischen Ozean.', 'Sezonowy układ wiatrów monsunowych zmieniający kierunek latem i zimą umożliwił żeglugę oceaniczną na Oceanie Indyjskim już w czasach starożytnych.', 'https://www.britannica.com/science/monsoon'),
  ('spicetrade', 1, 'The Dutch East India Company (VOC) and English East India Company were established around 1600 as the world''s first joint-stock corporations.', 'Die Niederlaendische und Englische Ostindien-Kompanie wurden um 1600 als weltweit erste Aktiengesellschaften gegruendet.', 'Holenderska Kompania Wschodnioindyjska (VOC) i brytyjska Kompania Wschodnioindyjska (EIC) powstały około 1600 roku jako pierwsze w świecie nowożytne spółki akcyjne.', 'https://www.britannica.com/topic/Dutch-East-India-Company'),
  ('spicetrade', 2, 'Maritime spice warehouses such as Hamburg''s Speicherstadt and Gdansk''s Motlawa granaries stored global botanical commodities under specialized customs regimes.', 'Die Hamburger Speicherstadt wurde zwischen 1883 und 1927 als zollfreies Lagerhausviertel fuer ueberseeische Waren erbaut.', 'Spichlerze portowe w Gdańsku nad Motławą oraz hamburska Speicherstadt stanowiły kluczowe węzły magazynowania przypraw korzennych i towarów kolonialnych w Europie.', 'https://nmm.pl'),
  ('spicetrade', 3, 'Black pepper accounted for more than half of the total volume of Asian spices imported into European harbors during the seventeenth century.', 'Schwarzer Pfeffer machte im 17. Jahrhundert ueber die Haelfte aller nach Europa importierten asiatischen Gewuerze aus.', 'Czarny pieprz stanowił ponad połowę całkowitego wolumenu przypraw azjatyckich sprowadzanych do europejskich portów w XVII wieku.', 'https://www.cambridge.org/core/books/trade-and-civilisation-in-the-indian-ocean/7074E3BE79586BEBA85E2DF7D114FDDF'),
  ('spicetrade', 4, 'Chartered trading companies maintained private armies and forts under royal monopoly privileges granted by sovereign crowns.', 'Handelskompanien unterhielten eigene Privatarmeen und Festungen unter koeniglich garantierten Handelsmonopolen.', 'Królewskie przywileje monopolowe pozwalały kompaniom handlowym utrzymywać własne armie, forty i floty wojenne w celu zwalczania konkurencji.', 'https://www.britannica.com/topic/chartered-company'),
  ('spicetrade', 5, '1500s: Timbuktu is a city of books. Traders and students meet in a desert city.', '1500er: Timbuktu wird zur Stadt der Buecher. Haendler und Schueler treffen sich in einer Wuestenstadt.', 'XVI wiek: Timbuktu miastem ksiąg. Kupcy i uczniowie spotykają się w pustynnym mieście.', 'https://en.wikipedia.org/wiki/Timbuktu'),
  ('spicetrade', 6, '1517: Luther starts the Reformation. A German monk argues about church rules, and printed leaflets spread his ideas.', '1517: Luther loest die Reformation aus. Ein deutscher Moench streitet ueber Kirchenregeln, und gedruckte Flugblaetter verbreiten seine Ideen.', '1517: Luter rozpoczyna reformację. Niemiecki mnich spiera się o zasady Kościoła, a drukowane ulotki roznoszą jego pomysły.', 'https://en.wikipedia.org/wiki/Martin_Luther'),
  ('spicetrade', 7, '1521: The Aztec capital falls. Tenochtitlan, a city on a lake, is conquered by Spain and its allies.', '1521: Die Aztekenhauptstadt faellt. Tenochtitlan, eine Stadt im See, wird von Spanien und seinen Verbuendeten erobert.', '1521: Upada stolica Azteków. Tenochtitlan, miasto na jeziorze, zostaje podbite przez Hiszpanię i jej sojuszników.', 'https://en.wikipedia.org/wiki/Fall_of_Tenochtitlan'),
  ('spicetrade', 8, '1526: Babur founds the Mughal Empire. A new empire grows in northern India.', '1526: Babur gruendet das Mogulreich. Im Norden Indiens waechst ein neues Reich.', '1526: Babur zakłada imperium Mogołów. Na północy Indii rośnie nowe imperium.', 'https://en.wikipedia.org/wiki/Mughal_Empire'),
  ('spicetrade', 9, '1543: Copernicus puts the Sun in the middle. A Polish astronomer says Earth travels around the Sun.', '1543: Kopernikus stellt die Sonne in die Mitte. Ein polnischer Astronom sagt, die Erde kreist um die Sonne.', '1543: Kopernik stawia Słońce w centrum. Polski astronom twierdzi, że Ziemia krąży wokół Słońca.', 'https://en.wikipedia.org/wiki/Nicolaus_Copernicus'),
  ('spicetrade', 10, '1571: Manila galleons link Asia and the Americas. Ships carry Chinese silk across the Pacific for silver.', '1571: Manila-Galeonen verbinden Asien und Amerika. Schiffe bringen chinesische Seide ueber den Pazifik gegen Silber.', '1571: Galeony z Manili łączą Azję i Ameryki. Statki wożą chiński jedwab przez Pacyfik w zamian za srebro.', 'https://en.wikipedia.org/wiki/Manila_galleon'),
  ('spicetrade', 11, '1602: The Dutch East India Company starts. People can buy shares in a trading fleet.', '1602: Die Niederlaendische Ostindien-Kompanie entsteht. Menschen koennen Anteile an einer Handelsflotte kaufen.', '1602: Powstaje Holenderska Kompania Wschodnioindyjska. Ludzie mogą kupować udziały we flocie handlowej.', 'https://en.wikipedia.org/wiki/Dutch_East_India_Company'),
  ('spicetrade', 12, '1603: Tokugawa rule begins in Japan. Peace comes and cities like Edo grow big.', '1603: In Japan beginnt die Tokugawa-Zeit. Es herrscht Frieden und Staedte wie Edo werden gross.', '1603: W Japonii zaczynają się rządy Tokugawów. Nastaje pokój, a miasta takie jak Edo rosną.', 'https://en.wikipedia.org/wiki/Tokugawa_shogunate'),
  ('spicetrade', 13, '1609: Galileo turns a telescope to the sky. He sees moons circling Jupiter.', '1609: Galilei richtet ein Fernrohr zum Himmel. Er sieht Monde, die um den Jupiter kreisen.', '1609: Galileusz kieruje teleskop w niebo. Widzi księżyce krążące wokół Jowisza.', 'https://en.wikipedia.org/wiki/Galileo_Galilei'),
  ('spicetrade', 14, '1632: Shah Jahan begins the Taj Mahal. Thousands of builders make a white marble tomb.', '1632: Schah Jahan beginnt den Taj Mahal. Tausende Bauleute errichten ein Grabmal aus weissem Marmor.', '1632: Szahdżahan rozpoczyna budowę Tadż Mahal. Tysiące budowniczych wznosi grobowiec z białego marmuru.', 'https://en.wikipedia.org/wiki/Taj_Mahal'),
  ('britishinindia', 0, 'The East India Company was granted an exclusive English trade monopoly charter by Queen Elizabeth I on 31 December 1600.', 'Die Ostindien-Kompanie erhielt am 31. Dezember 1600 ein koenigliches Handelsmonopol von Koenigin Elisabeth I.', 'Brytyjska Kompania Wschodnioindyjska otrzymała wyłączny przywilej monopolowy na handel azjatycki od królowej Elżbiety I w dniu 31 grudnia 1600 roku.', 'https://www.britannica.com/topic/East-India-Company'),
  ('britishinindia', 1, 'The Company acquired the Diwani (revenue collection rights) over Bengal following the Treaty of Allahabad in 1765.', 'Die Kompanie erlangte 1765 durch den Vertrag von Allahabad das Recht der Steuereinziehung (Diwani) in Bengalen.', 'Kompania uzyskała prawo poboru podatków gruntowych (Diwani) w Bengalu po traktacie w Allahabadzie w 1765 roku.', 'https://www.britannica.com/event/Treaty-of-Allahabad'),
  ('britishinindia', 2, 'Indian share of world industrial manufacturing dropped from approximately 25 percent in 1750 to under 3 percent by 1900.', 'Indiens Anteil an der weltweiten Industrieproduktion sank von rund 25 Prozent im Jahr 1750 auf unter 3 Prozent im Jahr 1900.', 'Udział Indii w światowej produkcji przemysłowej spadł z około 25 procent w 1750 roku do poniżej 3 procent w roku 1900.', 'https://www.cambridge.org/core/books/economic-history-of-india-18571947/72F18A370EF5EF4C2161A28A6993CEF7'),
  ('britishinindia', 3, 'The Government of India Act 1858 transferred corporate control from the East India Company directly to the British Crown.', 'Der Government of India Act 1858 uebertrug die Herrschaft von der Handelsgesellschaft direkt auf die britische Krone.', 'Ustawa Government of India Act z 1858 roku odebrała władzę prywatnej Kompanii i przekazała bezpośrednią kontrolę Koronie Brytyjskiej.', 'https://www.britannica.com/topic/Government-of-India-Act-1858'),
  ('britishinindia', 4, 'Railway construction in colonial India connected interior agricultural hinterlands directly to coastal export ports.', 'Der Eisenbahnbau im kolonialen Indien verband das landwirtschaftliche Binnenland direkt mit den Exportseehaefen.', 'Budowa kolei w Indiach kolonialnych łączyła rolnicze i surowcowe zaplecze kraju bezpośrednio z portami morskimi służącymi do eksportu surowców.', 'https://www.cambridge.org/core/books/railways-in-modern-india/E341F758C5A3764831B39F29E0436FF0'),
  ('britishinindia', 5, '1776: The United States declares independence. Thirteen colonies say they will rule themselves.', '1776: Die USA erklaeren ihre Unabhaengigkeit. Dreizehn Kolonien sagen, sie regieren sich selbst.', '1776: Stany Zjednoczone ogłaszają niepodległość. Trzynaście kolonii oświadcza, że będą rządzić się same.', 'https://en.wikipedia.org/wiki/United_States_Declaration_of_Independence'),
  ('britishinindia', 6, '1829: Steam locomotives race at Rainhill. Stephenson''s Rocket shows trains can be fast.', '1829: Dampflokomotiven fahren in Rainhill um die Wette. Stephensons Rocket zeigt, dass Zuege schnell sein koennen.', '1829: Parowozy ścigają się w Rainhill. Rakieta Stephensona pokazuje, że pociągi mogą być szybkie.', 'https://en.wikipedia.org/wiki/Stephenson%27s_Rocket'),
  ('britishinindia', 7, '1857: The Rebellion of 1857. Soldiers and others rise up against the East India Company.', '1857: Der Aufstand von 1857. Soldaten und andere erheben sich gegen die Ostindien-Kompanie.', '1857: Powstanie 1857 roku. Żołnierze i inni powstają przeciw Kompanii Wschodnioindyjskiej.', 'https://en.wikipedia.org/wiki/Indian_Rebellion_of_1857'),
  ('britishinindia', 8, '1868: Meiji Japan modernises. Japan builds railways and schools very quickly.', '1868: Das Meiji-Japan modernisiert sich. Japan baut sehr schnell Eisenbahnen und Schulen.', '1868: Japonia Meiji się modernizuje. Japonia bardzo szybko buduje koleje i szkoły.', 'https://en.wikipedia.org/wiki/Meiji_Restoration'),
  ('britishinindia', 9, '1869: The Suez Canal opens. Ships can sail from Europe to Asia without going around Africa.', '1869: Der Suezkanal wird eroeffnet. Schiffe koennen von Europa nach Asien fahren, ohne Afrika zu umrunden.', '1869: Otwarto Kanał Sueski. Statki mogą płynąć z Europy do Azji bez opływania Afryki.', 'https://en.wikipedia.org/wiki/Suez_Canal'),
  ('britishinindia', 10, '1869: The first US transcontinental railroad. Two railways meet in Utah and join east and west.', '1869: Die erste Eisenbahn quer durch die USA. Zwei Bahnlinien treffen sich in Utah und verbinden Ost und West.', '1869: Pierwsza kolej transkontynentalna w USA. Dwie linie kolejowe spotykają się w Utah i łączą wschód z zachodem.', 'https://en.wikipedia.org/wiki/First_transcontinental_railroad'),
  ('britishinindia', 11, '1879: Edison''s long-lasting light bulb. A glowing bulb lights a room for hours.', '1879: Edisons langlebige Gluehbirne. Eine leuchtende Birne erhellt einen Raum stundenlang.', '1879: Trwała żarówka Edisona. Świecąca żarówka oświetla pokój przez wiele godzin.', 'https://en.wikipedia.org/wiki/Thomas_Edison'),
  ('britishinindia', 12, '1885: Pasteur''s rabies vaccine. A doctor finds a way to protect people from a dangerous germ.', '1885: Pasteurs Tollwutimpfstoff. Ein Arzt findet einen Weg, Menschen vor einem gefaehrlichen Keim zu schuetzen.', '1885: Szczepionka Pasteura na wściekliznę. Lekarz znajduje sposób, by chronić ludzi przed groźnym zarazkiem.', 'https://en.wikipedia.org/wiki/Louis_Pasteur'),
  ('independence', 0, 'The Dandi Salt March covered 240 miles from Sabarmati Ashram to the Arabian Sea in March-April 1930.', 'Der Salzmarsch nach Dandi fuehrte im Maerz und April 1930 ueber 240 Meilen vom Sabarmati-Ashram an das Arabische Meer.', 'Marsz solny do Dandi przebył 240 mil z aśramu Sabarmati nad Morze Arabskie w marcu i kwietniu 1930 roku.', 'https://www.britannica.com/event/Salt-March'),
  ('independence', 1, 'The Indian Independence Act 1947 granted legislative independence to India on 15 August 1947.', 'Der Indian Independence Act 1947 gewaehrte Indien am 15. August 1947 die volle Unabhaengigkeit.', 'Ustawa Indian Independence Act z 1947 roku przyznała Indiom pełną suwerenność państwową w dniu 15 sierpnia 1947 roku.', 'https://www.legislation.gov.uk/ukpga/1947/30/enacted'),
  ('independence', 2, 'Dr. Bhimrao Ramji Ambedkar served as the chairman of the Drafting Committee for the Constitution of India.', 'Dr. Bhimrao Ramji Ambedkar leitete den Verfassungsausschuss fuer die demokratische Verfassung Indiens.', 'Dr Bhimrao Ramji Ambedkar przewodniczył komisji redagującej demokratyczną konstytucję Indii uchwaloną w 1949 roku.', 'https://www.britannica.com/biography/Bhimrao-Ramji-Ambedkar'),
  ('independence', 3, 'The Constitution of India came into effect on 26 January 1950, establishing universal adult franchise without property or gender restrictions.', 'Die Verfassung Indiens trat am 26. Januar 1950 in Kraft und verankerte das allgemeine Wahlrecht ohne Standes- oder Geschlechtergrenzen.', 'Konstytucja Indii weszła w życie 26 stycznia 1950 roku, ustanawiając powszechne prawo wyborcze bez cenzusu majątku czy płci.', 'https://www.india.gov.in/my-government/constitution-india'),
  ('independence', 4, 'The 1980 Polish Solidarity movement and the 1989 peaceful Leipzig demonstrations demonstrated that non-violent civic solidarity can overcome authoritarian rule.', 'Die Montagsdemonstrationen 1989 in Leipzig und die polnische Solidarność-Bewegung von 1980 bewiesen die Kraft gewaltlosen Buergermuts.', 'Powstanie Solidarności w 1980 roku w Polsce oraz demonstracje ze świecami w Lipsku w 1989 roku dowiodły, że pokojowa solidarność obywatelska potrafi przełamać dyktaturę.', 'https://www.bundesarchiv.de/themen-entdecken/online-ausstellungen/die-friedliche-revolution-1989/'),
  ('independence', 5, '1903: The Wright brothers fly. A small plane stays in the air for twelve seconds.', '1903: Die Gebrueder Wright fliegen. Ein kleines Flugzeug bleibt zwoelf Sekunden in der Luft.', '1903: Bracia Wright latają. Mały samolot utrzymuje się w powietrzu przez dwanaście sekund.', 'https://en.wikipedia.org/wiki/Wright_brothers'),
  ('independence', 6, '1914 to 1918: The First World War. Countries that had promised to help each other are pulled into a huge war.', '1914 bis 1918: Der Erste Weltkrieg. Laender, die sich Hilfe versprochen hatten, werden in einen riesigen Krieg gezogen.', '1914 do 1918: I wojna światowa. Kraje, które obiecały sobie pomoc, zostają wciągnięte w ogromną wojnę.', 'https://en.wikipedia.org/wiki/World_War_I'),
  ('independence', 7, '1915: Gandhi returns to India. A lawyer comes home from South Africa with a plan to protest peacefully.', '1915: Gandhi kehrt nach Indien zurueck. Ein Anwalt kehrt aus Suedafrika mit dem Plan zurueck, friedlich zu protestieren.', '1915: Gandhi wraca do Indii. Prawnik wraca z Afryki Południowej z planem pokojowego protestu.', 'https://en.wikipedia.org/wiki/Mahatma_Gandhi'),
  ('independence', 8, '1917: The Russian Revolution. The Tsar loses his throne and a new kind of government begins.', '1917: Die Russische Revolution. Der Zar verliert den Thron und eine neue Art von Regierung beginnt.', '1917: Rewolucja rosyjska. Car traci tron i zaczyna się nowy rodzaj rządów.', 'https://en.wikipedia.org/wiki/Russian_Revolution'),
  ('independence', 9, '1922: The Ottoman sultanate ends. A very old empire is replaced by a new country, Turkey.', '1922: Das osmanische Sultanat endet. Ein sehr altes Reich wird durch ein neues Land ersetzt, die Tuerkei.', '1922: Koniec sułtanatu osmańskiego. Bardzo stare imperium zostaje zastąpione nowym krajem, Turcją.', 'https://en.wikipedia.org/wiki/Abolition_of_the_Ottoman_sultanate'),
  ('independence', 10, '1928: Fleming finds penicillin. Mould on a dish kills germs around it.', '1928: Fleming entdeckt das Penicillin. Schimmel auf einer Schale toetet Keime in seiner Naehe.', '1928: Fleming odkrywa penicylinę. Pleśń na szalce zabija zarazki wokół siebie.', 'https://en.wikipedia.org/wiki/Alexander_Fleming'),
  ('independence', 11, '1939 to 1945: The Second World War. A huge war touches almost every country.', '1939 bis 1945: Der Zweite Weltkrieg. Ein riesiger Krieg erfasst fast jedes Land.', '1939 do 1945: II wojna światowa. Ogromna wojna dotyka niemal każdego kraju.', 'https://en.wikipedia.org/wiki/World_War_II'),
  ('independence', 12, '1941 to 1945: The Holocaust. During the war, the Nazi government hurt and killed millions of people, especially Jewish families. We remember so it never happens again.', '1941 bis 1945: Der Holocaust. Im Krieg verletzte und toetete die Nazi-Regierung Millionen Menschen, vor allem juedische Familien. Wir erinnern uns, damit es nie wieder geschieht.', '1941 do 1945: Holokaust. W czasie wojny rząd nazistowski krzywdził i zabijał miliony ludzi, zwłaszcza żydowskie rodziny. Pamiętamy, by to się nigdy nie powtórzyło.', 'https://en.wikipedia.org/wiki/Holocaust'),
  ('independence', 13, '1942: The Quit India Movement. While Europe is at war, Gandhi asks the British to leave India.', '1942: Die Quit-India-Bewegung. Waehrend Europa im Krieg ist, bittet Gandhi die Briten, Indien zu verlassen.', '1942: Ruch Quit India. Gdy Europa jest w stanie wojny, Gandhi prosi Brytyjczyków o opuszczenie Indii.', 'https://en.wikipedia.org/wiki/Quit_India_Movement'),
  ('independence', 14, '1943: The Bengal famine. Many families in Bengal cannot get enough food during the war.', '1943: Die Hungersnot in Bengalen. Viele Familien in Bengalen bekommen waehrend des Krieges nicht genug zu essen.', '1943: Głód w Bengalu. Wiele rodzin w Bengalu nie ma dość jedzenia w czasie wojny.', 'https://en.wikipedia.org/wiki/Bengal_famine_of_1943'),
  ('independence', 15, '1945: The first atomic bombs. Scientists learn how to release the power inside atoms, and the world sees how dangerous it is.', '1945: Die ersten Atombomben. Forscher lernen, die Kraft in Atomen freizusetzen, und die Welt sieht, wie gefaehrlich sie ist.', '1945: Pierwsze bomby atomowe. Naukowcy uczą się uwalniać moc atomu, a świat widzi, jak jest groźna.', 'https://en.wikipedia.org/wiki/Atomic_bombings_of_Hiroshima_and_Nagasaki'),
  ('independence', 16, '1947: India becomes independent. After a long struggle, India raises its own flag.', '1947: Indien wird unabhaengig. Nach langem Kampf hisst Indien seine eigene Flagge.', '1947: Indie stają się niepodległe. Po długiej walce Indie podnoszą własną flagę.', 'https://en.wikipedia.org/wiki/Partition_of_India'),
  ('independence', 17, '1948: The Marshall Plan rebuilds Europe. America sends money, food and machines to help broken cities in Europe.', '1948: Der Marshallplan baut Europa wieder auf. Amerika schickt Geld, Essen und Maschinen, um zerstoerte Staedte in Europa zu unterstuetzen.', '1948: Plan Marshalla odbudowuje Europę. Ameryka wysyła pieniądze, żywność i maszyny, by pomóc zniszczonym miastom Europy.', 'https://en.wikipedia.org/wiki/Marshall_Plan'),
  ('independence', 18, '1949: The People''s Republic of China is founded. A new government forms after a long civil war.', '1949: Die Volksrepublik China wird gegruendet. Nach einem langen Buergerkrieg entsteht eine neue Regierung.', '1949: Powstaje Chińska Republika Ludowa. Po długiej wojnie domowej powstaje nowy rząd.', 'https://en.wikipedia.org/wiki/People%27s_Republic_of_China'),
  ('independence', 19, '1960: The Year of Africa. Seventeen African countries become independent in one year.', '1960: Das Afrikajahr. Siebzehn afrikanische Laender werden in einem Jahr unabhaengig.', '1960: Rok Afryki. Siedemnaście krajów afrykańskich uzyskuje niepodległość w jednym roku.', 'https://en.wikipedia.org/wiki/Year_of_Africa'),
  ('ww1', 0, 'The Triple Entente and the Triple Alliance divided the major European powers into opposing military blocs prior to 1914.', 'Die Triple Entente und der Dreibund spalteten die europaeischen Grossmaechte vor 1914 in verfeindete Bloecke.', 'Trójprzymierze i Trójporozumienie (Ententa) podzieliły mocarstwa europejskie przed 1914 rokiem na dwa zbrojne bloki.', 'https://www.britannica.com/event/World-War-I/The-initial-stages-of-the-war'),
  ('ww1', 1, 'The assassination of Archduke Franz Ferdinand in Sarajevo triggered a rapid escalation of ultimatums and general mobilizations.', 'Das Attentat von Sarajevo fuehrte zu einer raschen Eskalation von Ultimaten und Generalmobilmachungen.', 'Zamach na arcyksięcia Franciszka Ferdynanda w Sarajewie uruchomił lawinę ultimatum dyplomatycznych i powszechnej mobilizacji armii.', 'https://www.britannica.com/event/assassination-of-Franz-Ferdinand'),
  ('ww1', 2, 'The Armistice of 11 November 1918 ended hostilities on the Western Front, coming into effect at 11:00 a.m. Paris time.', 'Der Waffenstillstand vom 11. November 1918 beendete die Kaempfe an der Westfront um 11:00 Uhr Pariser Zeit.', 'Rozejm w Compiègne z 11 listopada 1918 roku zakończył działania wojenne na froncie zachodnim o godzinie 11:00, stając się dniem odzyskania niepodległości przez Polskę.', 'https://www.britannica.com/event/Armistice'),
  ('ww1', 3, 'The Covenant of the League of Nations was integrated into the Treaty of Versailles in 1919 with its headquarters located in Geneva.', 'Die Satzung des Voelkerbundes wurde 1919 in den Versailler Vertrag aufgenommen, mit Sitz in Genf.', 'Pakt Ligi Narodów został włączony do traktatu wersalskiego w 1919 roku, a główną siedzibą organizacji została szwajcarska Genewa.', 'https://www.ungeneva.org/en/about/league-of-nations'),
  ('ww1', 4, 'The Peace Palace in The Hague was completed in 1913 to serve as the seat of the Permanent Court of Arbitration.', 'Der Friedenspalast in Den Haag wurde 1913 vollendet und dient als Sitz des Staendigen Schiedshofs und des IGH.', 'Pałac Pokoju w Hadze ukończony w 1913 roku stanowi siedzibę Stałego Trybunału Rozjemczego oraz Międzynarodowego Trybunału Sprawiedliwości.', 'https://www.vredespaleis.nl/building/history/?lang=en'),
  ('ww1', 5, '1903: The Wright brothers fly. A small plane stays in the air for twelve seconds.', '1903: Die Gebrueder Wright fliegen. Ein kleines Flugzeug bleibt zwoelf Sekunden in der Luft.', '1903: Bracia Wright latają. Mały samolot utrzymuje się w powietrzu przez dwanaście sekund.', 'https://en.wikipedia.org/wiki/Wright_brothers'),
